// Bespoke game rounds per concept id. Each entry: (concept) => [round, ...]
// Rounds use the engines in js/games. Anything not listed here falls back to generic concept checks.
import * as S from './stats.js';
import { dotPlot, histogram, barChart, scatter, boxPlot, curvePlot, lineChart, esc } from './charts.js';
import { estimateRound } from './games/estimate.js';
import { pickRound, quizRound, multiPickRound } from './games/pick.js';
import { corrRound, spearman } from './games/corr.js';
import { sigBetRound } from './games/sigbet.js';
import { predictRound } from './games/predict.js';
import { samplerRound } from './games/sampler.js';
import { buildRound } from './games/build.js';

const { randInt, choice, shuffle, normals, intsNormal, skewed, uniforms, mean, median, sd, variance, quantile, iqr, fmt } = S;
const R = S.rand;
const pct = (x) => `${Math.round(x * 100)}%`;
const list = (a) => a.map((v) => fmt(v)).join(', ');

// Mixture generator used by many centre/spread games: symmetric, skewed, or with an outlier.
function mixData(n = randInt(8, 30)) {
  const kind = choice(['sym', 'skewL', 'skewR', 'outlier']);
  if (kind === 'sym') return intsNormal(n, randInt(30, 70), randInt(5, 15), 0, 100);
  if (kind === 'skewR') return skewed(n, randInt(15, 30), 0.5, true).map((v) => Math.min(v, 120));
  if (kind === 'skewL') return skewed(n, randInt(15, 30), 0.5, false);
  const base = intsNormal(n - 1, randInt(30, 50), randInt(4, 8), 5, 80);
  return [...base, randInt(95, 120)];
}
const domainOf = (d, padFrac = 0.1) => { const lo = Math.min(...d), hi = Math.max(...d), p = (hi - lo) * padFrac || 1; return [Math.floor(lo - p), Math.ceil(hi + p)]; };

// Quick ESTIMATE builders.
const est = (prompt, data, statFn, tolFn, extra = {}) => {
  const truth = statFn(data);
  return estimateRound({ prompt, data, truth, tolerance: tolFn(data, truth), domain: domainOf(data), ...extra });
};
const scenarioPick = (prompt, pool, k = 4) => {
  const item = choice(pool);
  const wrong = shuffle(pool.filter((p) => p.answer !== item.answer).map((p) => p.answer).filter((v, i, a) => a.indexOf(v) === i)).slice(0, k - 1);
  const opts = shuffle([item.answer, ...wrong]);
  return quizRound({ prompt: `${prompt}<br><span class="scenario">${esc(item.text)}</span>`, choices: opts, answer: opts.indexOf(item.answer), why: item.why });
};
// Two-way text classification used for sort-style games.
const classify = (prompt, pool, labels) => {
  const item = choice(pool);
  return quizRound({ prompt: `${prompt}<br><span class="scenario">${esc(item.text)}</span>`, choices: labels, answer: labels.indexOf(item.answer), why: item.why });
};
const repeat = (n, fn) => Array.from({ length: n }, fn);

export const bespoke = {};

/* =========================== World 1: Data Island =========================== */
const VARS = [
  ['Eye colour', 'Categorical', 'Nominal'], ['Height in cm', 'Numerical', 'Ratio'], ['ZIP / postcode', 'Categorical', 'Nominal'], ['Jersey number', 'Categorical', 'Nominal'],
  ['Phone number', 'Categorical', 'Nominal'], ['Temperature in °C', 'Numerical', 'Interval'], ['Temperature in kelvin', 'Numerical', 'Ratio'], ['Satisfaction: poor/fair/good/excellent', 'Categorical', 'Ordinal'],
  ['Number of siblings', 'Numerical', 'Ratio'], ['Blood type', 'Categorical', 'Nominal'], ['Year of birth', 'Numerical', 'Interval'], ['Income in dollars', 'Numerical', 'Ratio'],
  ['Shoe size', 'Numerical', 'Interval'], ['Finishing place in a race (1st, 2nd…)', 'Categorical', 'Ordinal'], ['Weight in kg', 'Numerical', 'Ratio'], ['Credit-card number', 'Categorical', 'Nominal'],
  ['Pain score 0–10', 'Categorical', 'Ordinal'], ['Reaction time in ms', 'Numerical', 'Ratio'], ['Country of birth', 'Categorical', 'Nominal'], ['IQ score', 'Numerical', 'Interval'],
  ['Education level (school / bachelor / master / PhD)', 'Categorical', 'Ordinal'], ['Distance to work in km', 'Numerical', 'Ratio'], ['Bus route number', 'Categorical', 'Nominal'], ['Calendar date', 'Numerical', 'Interval'],
  ['Movie rating out of 5 stars', 'Categorical', 'Ordinal'], ['Number of cars sold', 'Numerical', 'Ratio'], ['pH of a solution', 'Numerical', 'Interval'], ['Age in years', 'Numerical', 'Ratio'],
];
const TRAPS = new Set(['ZIP / postcode', 'Jersey number', 'Phone number', 'Credit-card number', 'Bus route number']);
const typePool = VARS.map(([text, answer]) => ({ text, answer, why: TRAPS.has(text) ? `“${text}” is stored as digits but you cannot sensibly average it: it is a label, so categorical.` : answer === 'Numerical' ? `You can do arithmetic on “${text}”, so it is numerical.` : `“${text}” puts each case into a named bucket, so it is categorical.` }));
bespoke['W1.02'] = () => repeat(5, () => classify('Is this variable <b>categorical</b> or <b>numerical</b>? Ask: can I sensibly average it?', typePool, ['Categorical', 'Numerical']));

const SCALE_WHY = { Nominal: 'labels with no order', Ordinal: 'ordered categories with unequal gaps', Interval: 'equal gaps but no true zero (zero does not mean “none”)', Ratio: 'equal gaps and a true zero, so “twice as much” makes sense' };
const scalePool = VARS.map(([text, , answer]) => ({ text, answer, why: `“${text}” is ${answer.toLowerCase()}: ${SCALE_WHY[answer]}.` }));
const scaleRound = () => classify('Which <b>level of measurement</b> is this variable?', scalePool, ['Nominal', 'Ordinal', 'Interval', 'Ratio']);
for (const id of ['W1.03', 'W1.04', 'W1.05', 'W1.06']) bespoke[id] = () => repeat(5, scaleRound);

const DISC = [['Number of children', 'Discrete'], ['Height', 'Continuous'], ['Goals scored in a match', 'Discrete'], ['Time to run 100 m', 'Continuous'], ['Number of emails received today', 'Discrete'], ['Body temperature', 'Continuous'],
  ['Cars in a car park', 'Discrete'], ['Weight of a parcel', 'Continuous'], ['Dice roll', 'Discrete'], ['Rainfall in mm', 'Continuous'], ['Shoe size (sold in half sizes)', 'Discrete'], ['Voltage', 'Continuous'], ['Number of defective items', 'Discrete'], ['Age (exact)', 'Continuous']];
bespoke['W1.07'] = () => repeat(5, () => classify('Is this variable <b>discrete</b> (countable jumps) or <b>continuous</b> (any value in a range)?', DISC.map(([text, answer]) => ({ text, answer, why: answer === 'Discrete' ? `“${text}” comes in countable steps; there is nothing between 2 and 3.` : `“${text}” can take any value in a range; between any two values there is another.` })), ['Discrete', 'Continuous']));

const POPSAMP = [
  { text: 'A pollster phones 1,200 voters to learn what all 40 million voters think.', q: 'What is the population?', answer: 'All 40 million voters', wrong: ['The 1,200 voters phoned', 'The pollster', 'The 1,200 answers'] },
  { text: 'A pollster phones 1,200 voters to learn what all 40 million voters think.', q: 'What is the sample?', answer: 'The 1,200 voters phoned', wrong: ['All 40 million voters', 'The election result', 'The phone company'] },
  { text: 'A lab tests 50 light bulbs from a batch of 10,000 to estimate average lifetime.', q: 'What is the population?', answer: 'The batch of 10,000 bulbs', wrong: ['The 50 bulbs tested', 'The average lifetime', 'The lab'] },
  { text: 'A biologist measures 30 fish netted from a lake with roughly 5,000 fish.', q: 'What is the sample?', answer: 'The 30 fish netted', wrong: ['All 5,000 fish in the lake', 'The lake', 'The net'] },
  { text: 'A school checks every pupil’s height during the annual medical.', q: 'This is…', answer: 'A census: the whole population was measured', wrong: ['A sample of the pupils', 'A biased sample', 'An experiment'] },
];
bespoke['W1.08'] = () => repeat(4, () => { const it = choice(POPSAMP); const opts = shuffle([it.answer, ...it.wrong]); return quizRound({ prompt: `${it.q}<br><span class="scenario">${esc(it.text)}</span>`, choices: opts, answer: opts.indexOf(it.answer), why: 'The population is everyone you want to describe; the sample is the part you actually measured.' }); });

const SYMBOLS = [['μ (mu)', 'Parameter', 'population mean'], ['x̄ (x-bar)', 'Statistic', 'sample mean'], ['σ (sigma)', 'Parameter', 'population standard deviation'], ['s', 'Statistic', 'sample standard deviation'], ['p', 'Parameter', 'population proportion'], ['p̂ (p-hat)', 'Statistic', 'sample proportion'], ['ρ (rho)', 'Parameter', 'population correlation'], ['r', 'Statistic', 'sample correlation'], ['β (beta)', 'Parameter', 'population regression slope'], ['b', 'Statistic', 'estimated slope from a sample'], ['N', 'Parameter', 'population size'], ['n', 'Statistic', 'sample size']];
bespoke['W1.09'] = () => repeat(6, () => { const [sym, ans, what] = choice(SYMBOLS); return quizRound({ prompt: `Greek or Roman? Is <b>${sym}</b> a parameter (describes the population) or a statistic (computed from a sample)?`, choices: ['Parameter', 'Statistic'], answer: ans === 'Parameter' ? 0 : 1, why: `${sym} is the ${what}: a ${ans.toLowerCase()}. Greek letters are usually parameters; Roman letters are usually statistics.` }); });

const CAUSE = [
  { text: 'Does the amount of fertiliser change tomato yield?', iv: 'Amount of fertiliser', dv: 'Tomato yield', other: ['Type of tomato', 'The gardener'] },
  { text: 'Does hours of sleep affect exam score?', iv: 'Hours of sleep', dv: 'Exam score', other: ['The exam subject', 'Age of the student'] },
  { text: 'Does caffeine dose change reaction time?', iv: 'Caffeine dose', dv: 'Reaction time', other: ['Time of day', 'Brand of coffee'] },
  { text: 'Does advertising spend drive weekly sales?', iv: 'Advertising spend', dv: 'Weekly sales', other: ['Store location', 'Day of the week'] },
  { text: 'Does the new drug lower blood pressure?', iv: 'Drug vs placebo', dv: 'Blood pressure', other: ['Patient weight', 'Hospital'] },
  { text: 'Does study-group size affect how much students remember?', iv: 'Study-group size', dv: 'Amount remembered', other: ['Classroom', 'Textbook used'] },
];
const causeRound = (which) => { const it = choice(CAUSE); const ans = which === 'iv' ? it.iv : it.dv; const opts = shuffle([it.iv, it.dv, ...it.other]); return quizRound({ prompt: `Which is the <b>${which === 'iv' ? 'independent' : 'dependent'}</b> variable?<br><span class="scenario">${esc(it.text)}</span>`, choices: opts, answer: opts.indexOf(ans), why: `The independent variable is what is changed or compared (${it.iv}); the dependent variable is the outcome measured (${it.dv}).` }); };
bespoke['W1.10'] = () => repeat(5, () => causeRound('iv'));
bespoke['W1.11'] = () => repeat(5, () => causeRound('dv'));

const LURK = [
  { text: 'Ice-cream sales and drowning deaths rise together every summer.', answer: 'Hot weather', wrong: ['Ice-cream flavour', 'Lifeguard pay', 'Pool depth'] },
  { text: 'Children with bigger shoes read better.', answer: 'Age', wrong: ['Shoe brand', 'Eyesight', 'Reading lamp brightness'] },
  { text: 'Cities with more churches have more crime.', answer: 'City population size', wrong: ['Religion', 'Church architecture', 'Sermon length'] },
  { text: 'People who carry lighters get lung cancer more often.', answer: 'Smoking', wrong: ['Lighter fluid', 'Pocket size', 'Hand dominance'] },
  { text: 'Coffee drinkers have more heart disease.', answer: 'Smoking (more common among coffee drinkers)', wrong: ['Milk in coffee', 'Cup size', 'Café music'] },
  { text: 'Countries with more Nobel laureates eat more chocolate.', answer: 'National wealth', wrong: ['Cocoa percentage', 'Chocolate brand', 'Climate for cocoa'] },
];
bespoke['W1.12'] = () => repeat(4, () => { const it = choice(LURK); const opts = shuffle([it.answer, ...it.wrong]); return quizRound({ prompt: `Lurker hunt: which <b>confounding variable</b> could explain this link?<br><span class="scenario">${esc(it.text)}</span>`, choices: opts, answer: opts.indexOf(it.answer), why: `${it.answer} affects both variables, creating the association without either causing the other.` }); });

const DESCINF = [['The average age in this classroom is 14.2 years.', 'Descriptive'], ['Based on our sample, we estimate 52% of voters support the bill.', 'Inferential'], ['Sales rose 8% last quarter compared with the previous one.', 'Descriptive'], ['The trial suggests the drug lowers blood pressure in the population of patients.', 'Inferential'], ['The tallest player on the team is 2.01 m.', 'Descriptive'], ['The poll’s margin of error is ±3 points.', 'Inferential'], ['The median house price in the survey was £240,000.', 'Descriptive'], ['We are 95% confident the true mean lies between 4.1 and 4.9.', 'Inferential']];
bespoke['W1.13'] = () => repeat(5, () => classify('Is this statement <b>descriptive</b> (summarises the data in hand) or <b>inferential</b> (generalises beyond it)?', DESCINF.map(([text, answer]) => ({ text, answer, why: answer === 'Descriptive' ? 'It only summarises the data that were actually collected.' : 'It makes a claim about a wider population or future cases, with uncertainty.' })), ['Descriptive', 'Inferential']));

bespoke['W1.14'] = () => repeat(3, () => {
  const cats = shuffle(['Red', 'Blue', 'Green', 'Yellow']).slice(0, 3);
  const vals = Array.from({ length: randInt(12, 24) }, () => choice(cats));
  const target = choice(cats); const k = vals.filter((v) => v === target).length;
  return estimateRound({ prompt: `Tally tower: what is the <b>relative frequency</b> of <b>${target}</b> in this list?`, view: `<div class="scenario">${vals.join(' · ')}</div>`, truth: k / vals.length, tolerance: 0.08, min: 0, max: 1, step: 0.01, explain: `${target} appears ${k} times out of ${vals.length}: ${k}/${vals.length} = ${fmt(k / vals.length, 3)}.` });
});
bespoke['W1.15'] = () => repeat(3, () => {
  const xs = intsNormal(randInt(4, 6), 10, 5, 1, 20); const t = S.sum(xs);
  return estimateRound({ prompt: `Sigma sums: with x = (${xs.join(', ')}), what is <b>Σxᵢ</b>?`, truth: t, tolerance: 4, min: 0, max: Math.max(60, t + 20), step: 1, explain: `Σ means “add them all up”: ${xs.join(' + ')} = ${t}.` });
});
bespoke['W1.16'] = () => repeat(3, () => {
  const n = randInt(12, 30); const k = randInt(2, n - 2); const data = shuffle([...Array(k).fill(1), ...Array(n - k).fill(0)]);
  return estimateRound({ prompt: `Flip to one: ${n} people were asked a yes/no question (yes = 1). What is the <b>mean</b> of these 0/1 values?`, data, truth: k / n, tolerance: 0.1, min: 0, max: 1, step: 0.01, domain: [-0.2, 1.2], explain: `The mean of a 0/1 variable is the proportion of ones: ${k}/${n} = ${fmt(k / n, 3)}.` });
});

/* =========================== World 2: Centre Cove =========================== */
bespoke['W2.01'] = () => repeat(4, () => est('Balance beam: where does this dot plot <b>balance</b>? Place the mean.', mixData(), mean, (d) => 0.5 * sd(d), { truthLabel: 'mean', explain: (t, d) => `Sum ${S.sum(d)} ÷ ${d.length} = ${fmt(t)}. Deviations above and below the mean cancel out exactly.` }));
bespoke['W2.02'] = () => repeat(4, () => est('Middle marker: place the <b>median</b> so half the dots sit on each side.', mixData(randInt(7, 25)), median, (d) => 0.4 * sd(d) + 0.5, { truthLabel: 'median', explain: (t, d) => `Sorted: ${list([...d].sort((a, b) => a - b))}. Middle ${d.length % 2 ? 'value' : 'pair averages to'} ${fmt(t)}; the mean is ${fmt(mean(d))}.` }));
bespoke['W2.03'] = () => repeat(4, () => {
  const cats = shuffle(['Apple', 'Pear', 'Plum', 'Fig', 'Kiwi']).slice(0, 4);
  const r = R(); let counts;
  if (r < 0.1) counts = cats.map(() => 6);
  else if (r < 0.4) { const hi = randInt(8, 12); counts = cats.map(() => randInt(2, hi - 2)); const [a, b] = shuffle([0, 1, 2, 3]); counts[a] = hi; counts[b] = hi; }
  else { counts = cats.map(() => randInt(2, 8)); counts[randInt(0, 3)] = randInt(10, 14); }
  const top = Math.max(...counts); const modes = cats.filter((_, i) => counts[i] === top);
  const answer = modes.length === cats.length ? 'No mode (all counts equal)' : modes.length === 2 ? `Two modes: ${modes.join(' and ')}` : `Mode: ${modes[0]}`;
  const choices = shuffle([...new Set([answer, ...cats.map((c) => `Mode: ${c}`), 'No mode (all counts equal)', `Two modes: ${cats[0]} and ${cats[1]}`])]).slice(0, 5);
  if (!choices.includes(answer)) choices[0] = answer;
  return quizRound({ prompt: `Peak finder: what is the <b>mode</b> of this bar chart?${barChart(cats.map((c, i) => ({ label: c, value: counts[i] })), { height: 200 })}`, choices, answer: choices.indexOf(answer), why: `The mode is the <i>category</i> under the tallest bar, not the height. Counts: ${cats.map((c, i) => `${c} ${counts[i]}`).join(', ')}.` });
});
bespoke['W2.04'] = () => repeat(3, () => {
  const scores = [randInt(40, 100), randInt(40, 100), randInt(40, 100)]; const w = choice([[50, 30, 20], [60, 25, 15], [40, 40, 20], [70, 20, 10]]);
  const t = S.sum(scores.map((s, i) => s * w[i])) / 100;
  return estimateRound({ prompt: `Grade mixer: exam ${scores[0]} (weight ${w[0]}%), coursework ${scores[1]} (${w[1]}%), project ${scores[2]} (${w[2]}%). What is the <b>weighted mean</b>?`, truth: t, tolerance: 5, min: 40, max: 100, step: 0.5, explain: `(${scores.map((s, i) => `${s}×${w[i]}`).join(' + ')}) / 100 = ${fmt(t)}. The plain mean would be ${fmt(mean(scores))}.` });
});
bespoke['W2.05'] = () => repeat(3, () => {
  const d = [...skewed(randInt(20, 36), 20, 0.5), ...repeat(randInt(1, 3), () => randInt(150, 220))];
  const k = Math.floor(d.length * 0.1); const s = [...d].sort((a, b) => a - b).slice(k, d.length - k); const t = mean(s);
  return estimateRound({ prompt: `Trim trim: estimate the <b>10% trimmed mean</b> (drop the lowest and highest 10% of values, then average).`, data: d, truth: t, tolerance: 0.3 * sd(d), domain: domainOf(d), explain: `Dropping ${k} values from each end leaves ${s.length}; their mean is ${fmt(t)}. Plain mean ${fmt(mean(d))}, median ${fmt(median(d))}: trimming pulls the mean toward the median.` });
});
bespoke['W2.06'] = () => repeat(3, () => {
  const g = repeat(randInt(4, 6), () => +(0.6 + R() * 1.0).toFixed(2));
  const gm = Math.exp(mean(g.map(Math.log))); const t = (gm - 1) * 100; const am = (mean(g) - 1) * 100;
  return estimateRound({ prompt: `Growth gauge: an investment grew by ${g.map((x) => `${x >= 1 ? '+' : ''}${Math.round((x - 1) * 100)}%`).join(', ')} in successive years. What <b>constant yearly rate</b> gives the same final value?`, view: barChart(g.map((x, i) => ({ label: `Yr ${i + 1}`, value: Math.round((x - 1) * 100) })), { height: 160 }), truth: t, tolerance: 3, min: -40, max: 60, step: 0.5, unit: '%', explain: `Geometric mean of the factors = (${g.join('×')})^(1/${g.length}) = ${fmt(gm, 3)}, i.e. ${fmt(t, 1)}% per year. The arithmetic mean of rates (${fmt(am, 1)}%) overstates it.` });
});
bespoke['W2.07'] = () => repeat(3, () => {
  const a = randInt(10, 100), b = randInt(10, 100); const t = 2 / (1 / a + 1 / b);
  return estimateRound({ prompt: `Round trip: a boat sails to the island at <b>${a} km/h</b> and back at <b>${b} km/h</b>. What is its average speed for the whole trip?`, truth: t, tolerance: 5, min: 0, max: 110, step: 0.5, unit: ' km/h', explain: `Same distance each way, so total distance ÷ total time = 2/(1/${a} + 1/${b}) = ${fmt(t)} km/h, the harmonic mean. The arithmetic mean ${fmt((a + b) / 2)} is too high.` });
});
bespoke['W2.08'] = () => repeat(3, () => est('Two-point centre: estimate the <b>midrange</b> (halfway between min and max).', mixData(randInt(10, 20)), (d) => (Math.min(...d) + Math.max(...d)) / 2, (d) => 0.3 * sd(d) + 0.5, { truthLabel: 'midrange', explain: (t, d) => `(${Math.min(...d)} + ${Math.max(...d)}) / 2 = ${fmt(t)}. Mean ${fmt(mean(d))}, median ${fmt(median(d))}: the midrange uses only two values, so one outlier drags it far.` }));
bespoke['W2.09'] = () => repeat(2, () => {
  const d = intsNormal(choice([9, 11, 13]), 50, 8, 20, 80); const i = d.indexOf(Math.max(...d)); const shift = +(sd(d) * (0.5 + R() * 1.5)).toFixed(1);
  const m0 = mean(d), med0 = median(d);
  return buildRound({ prompt: `Outlier tug: drag the highlighted dot so the <b>mean rises by ${fmt(shift)}</b> (from ${fmt(m0)} to ${fmt(m0 + shift)}) while the <b>median stays at ${fmt(med0)}</b>.`, data: d, movable: [i], stat: mean, statName: 'mean', target: m0 + shift, tolerance: 0.15 * shift + 0.3, domain: [0, 160], extra: { name: 'median', fn: median }, explain: (v) => `${median(v) === med0 ? 'The median did not move' : `The median moved to ${fmt(median(v))}`}: one dot can drag the mean anywhere, but the median only cares about the middle of the pack.` });
});
const WHICHAVG = [
  { text: 'Typical house price in a city where a few mansions sell for millions.', answer: 'Median', why: 'Prices are right-skewed; the median resists the mansions.' },
  { text: 'Most common shirt size to stock in a shop.', answer: 'Mode', why: 'Sizes are categories; you want the most frequent one.' },
  { text: 'Average yearly return of an investment over 5 years.', answer: 'Geometric mean', why: 'Growth compounds multiplicatively, so use the geometric mean.' },
  { text: 'Average speed over a route driven at several speeds for equal distances.', answer: 'Harmonic mean', why: 'Equal distances at different rates call for the harmonic mean.' },
  { text: 'Typical height of adult women (roughly symmetric data).', answer: 'Mean', why: 'Symmetric numerical data: the mean uses all the information.' },
  { text: 'Typical household income in a country.', answer: 'Median', why: 'Income is heavily right-skewed; the mean is pulled up by top earners.' },
  { text: 'The favourite colour reported by a class.', answer: 'Mode', why: 'Nominal data have no order; only the mode makes sense.' },
  { text: 'Average mark on an exam where marks are roughly bell-shaped.', answer: 'Mean', why: 'Symmetric numerical data suit the mean.' },
];
bespoke['W2.10'] = () => repeat(5, () => scenarioPick('Which average answers this question best?', WHICHAVG, 5));
bespoke['W2.11'] = () => repeat(2, () => {
  const four = intsNormal(4, 50, 10, 20, 80); const target = randInt(40, 60); const need = 5 * target - S.sum(four);
  return buildRound({ prompt: `Zero sum shore: four values are fixed (${four.join(', ')}). Drag the fifth so the <b>mean is ${target}</b>, which makes the deviations sum to zero.`, data: [...four, 50], movable: [4], stat: mean, statName: 'mean', target, tolerance: 1.5, domain: [0, Math.max(120, need + 10)], extra: { name: 'Σ(xᵢ − target)', fn: (v) => S.sum(v.map((x) => x - target)) }, explain: (v) => `The fifth value needed to be 5×${target} − ${S.sum(four)} = ${need}. Deviations from the mean always add to zero, which is why spread measures square or take absolute values.` });
});

/* =========================== World 3: Spread Shores =========================== */
bespoke['W3.01'] = () => repeat(3, () => est('Stretch guess: estimate the <b>range</b> (max − min).', mixData(randInt(10, 25)), S.range, (d, t) => 0.15 * t + 1, { chart: 'dot', min: 0, max: null, explain: (t, d) => `${Math.max(...d)} − ${Math.min(...d)} = ${t}.` }));
bespoke['W3.02'] = () => repeat(3, () => est('Average distance: estimate the <b>mean absolute deviation</b> (average distance of a dot from the mean).', intsNormal(randInt(10, 20), 50, randInt(5, 15), 0, 100), (d) => mean(d.map((x) => Math.abs(x - mean(d)))), (d, t) => 0.35 * t + 0.5, { min: 0, max: null, explain: (t, d) => `Mean ${fmt(mean(d))}; the absolute deviations average to ${fmt(t)}. Compare SD ${fmt(sd(d))}: squaring punishes the far dots more.` }));
bespoke['W3.03'] = () => repeat(3, () => { const d = intsNormal(randInt(30, 60), 50, randInt(4, 12), 0, 100); return estimateRound({ prompt: 'Square patch: estimate the <b>variance</b> (average squared distance from the mean).', data: d, chart: 'hist', truth: variance(d), tolerance: 0.5 * variance(d), min: 0, max: Math.ceil(variance(d) * 2.5 + 10), step: 0.5, domain: domainOf(d), explain: (t, dd) => `SD is ${fmt(sd(dd))}, so the variance is ${fmt(sd(dd))}² = ${fmt(t)}. Its units are squared, which is why we usually report the SD.` }); });
bespoke['W3.04'] = () => repeat(4, () => { const d = intsNormal(randInt(15, 40), 50, randInt(3, 18), 0, 100); return estimateRound({ prompt: 'Ruler of spread: estimate the <b>standard deviation</b>. Tip: about two-thirds of the dots lie within one SD of the mean.', data: d, truth: sd(d), tolerance: 0.4 * sd(d), min: 0, max: 30, step: 0.1, domain: domainOf(d), explain: (t, dd) => `Mean ${fmt(mean(dd))}; SD ${fmt(t)}. Range/4 is a quick rough guess: ${fmt(S.range(dd) / 4)}.` }); });
