const SPACES = [['Roll two dice', 36], ['Flip three coins', 8], ['Flip a coin and roll a die', 12], ['Flip two coins', 4], ['Roll one die', 6], ['Pick one card from a standard deck', 52], ['Roll a die twice and record the ordered pair', 36], ['Flip four coins', 16]];
