function twoWay() { const a = randInt(10, 40), b = randInt(10, 40), c = randInt(10, 40), d = randInt(10, 40); return { a, b, c, d, N: a + b + c + d, html: `<table class="tbl"><tr><th></th><th>Likes tea</th><th>No tea</th><th>Total</th></tr><tr><th>Morning person</th><td>${a}</td><td>${b}</td><td>${a + b}</td></tr><tr><th>Night owl</th><td>${c}</td><td>${d}</td><td>${c + d}</td></tr><tr><th>Total</th><td>${a + c}</td><td>${b + d}</td><td>${a + b + c + d}</td></tr></table>` }; }
