function bayesCase() { const prev = choice([0.001, 0.005, 0.01, 0.02, 0.05, 0.1]), sens = choice([0.9, 0.95, 0.99]), spec = choice([0.9, 0.95, 0.98, 0.99]); const ppv = prev * sens / (prev * sens + (1 - prev) * (1 - spec)); return { prev, sens, spec, ppv }; }
