function spinner() { const vals = [0, 1, 2, 5, 10].slice(0, randInt(3, 5)); let w = vals.map(() => randInt(1, 5)); const tot = S.sum(w); const probs = w.map((x) => x / tot); const ev = S.sum(vals.map((v, i) => v * probs[i])); const vr = S.sum(vals.map((v, i) => (v - ev) ** 2 * probs[i])); const html = `<table class="tbl"><tr><th>Prize x</th>${vals.map((v) => `<td>£${v}</td>`).join('')}</tr><tr><th>P(X = x)</th>${probs.map((p) => `<td>${fmt(p, 2)}</td>`).join('')}</tr></table>`; const draw = () => { let r = R(); for (let i = 0; i < vals.length; i++) { r -= probs[i]; if (r <= 0) return vals[i]; } return vals[vals.length - 1]; }; return { vals, probs, ev, sdv: Math.sqrt(vr), html, draw }; }
bespoke['W4.13'] = () => repeat(3, () => { const s = spinner(); const k = choice(s.vals.slice(1)); const truth = S.sum(s.vals.map((v, i) => (v >= k ? s.probs[i] : 0))); return estimateRound({ prompt: `Number machine: X is the prize from one spin. P(<b>X ≥ ${k}</b>)?`, view: s.html, truth, tolerance: 0.1, min: 0, max: 1, step: 0.01, explain: `Add the probabilities of every value ≥ ${k}: ${fmt(truth, 2)}. A random variable is just a number attached to each outcome with a probability.` }); });
bespoke['W4.14'] = () => repeat(2, () => { const s = spinner(); return predictRound({ prompt: 'Fair price: what is the <b>expected value</b> (long-run average prize) of one spin? That is the fair price to play.', view: s.html, truth: s.ev, tolerance: 1.5, trial: s.draw, min: 0, max: 10, step: 0.05, unit: ' £', label: 'Average prize so far', explain: `E[X] = Σ x·P(x) = ${s.vals.map((v, i) => `${v}×${fmt(s.probs[i], 2)}`).join(' + ')} = £${fmt(s.ev)}.` }); });
bespoke['W4.15'] = () => repeat(3, () => { const s = spinner(); return estimateRound({ prompt: `Risky spinner: the expected prize is £${fmt(s.ev)}. Estimate the <b>standard deviation</b> of the prize.`, view: s.html, truth: s.sdv, tolerance: 0.4 * s.sdv + 0.3, min: 0, max: 6, step: 0.05, explain: `Var = Σ (x − μ)²·P(x) = ${fmt(s.sdv ** 2)}, so SD = ${fmt(s.sdv)}. Two games with the same expected value can differ hugely in risk.` }); });
bespoke['W4.16'] = () => [(() => { const p = choice([0.3, 0.6, 0.7, 0.45]); return predictRound({ prompt: `Converge cove: a biased coin lands heads with probability <b>${p}</b>. After 2,000 flips, what will the running proportion of heads be close to? Watch how wild it is early on.`, truth: p, tolerance: 0.1, trial: () => (R() < p ? 1 : 0), trials: 2000, explain: `The law of large numbers: the running average settles toward ${p}. It never “corrects” past flips; it simply drowns them.` }); })()];
const fact = (n) => (n <= 1 ? 1 : n * fact(n - 1));
bespoke['W4.17'] = () => repeat(3, () => { const n = randInt(4, 7), k = randInt(2, 3); const perm = fact(n) / fact(n - k); const comb = perm / fact(k); const choices = shuffle([...new Set([perm, comb, n * k, n ** k])]).slice(0, 4); return quizRound({ prompt: `Line them up: <b>${n}</b> runners, how many ways to award gold, silver and bronze${k === 2 ? ' (just gold and silver)' : ''}? Order matters.`, choices: choices.map((v) => v.toLocaleString()), answer: choices.indexOf(perm), why: `Permutations: ${n}!/(${n}−${k})! = ${perm.toLocaleString()}. Order matters, so do not divide by k!.` }); });
bespoke['W4.18'] = () => repeat(3, () => { const n = randInt(5, 9), k = randInt(2, 4); const comb = fact(n) / (fact(k) * fact(n - k)); const perm = fact(n) / fact(n - k); const choices = shuffle([...new Set([comb, perm, n * k, comb * 2])]).slice(0, 4); return quizRound({ prompt: `Pick a team: choose <b>${k}</b> people from <b>${n}</b> for a committee. How many different committees? Order does not matter.`, choices: choices.map((v) => v.toLocaleString()), answer: choices.indexOf(comb), why: `Combinations: C(${n}, ${k}) = ${n}! / (${k}!·${n - k}!) = ${comb.toLocaleString()}. Each committee was counted ${k}! times among the ${perm} orderings.` }); });
bespoke['W4.19'] = () => repeat(4, () => { const p = choice([0.2, 0.25, 0.5, 0.75, 0.8, 0.1, 0.6]); const toOdds = R() < 0.5; const truth = toOdds ? p / (1 - p) : p; return toOdds ? estimateRound({ prompt: `Odds converter: probability <b>${p}</b> corresponds to what <b>odds</b> (for : against, as a single number)?`, truth, tolerance: 0.3 * truth + 0.1, min: 0, max: 5, step: 0.05, explain: `Odds = p / (1 − p) = ${p} / ${fmt(1 - p)} = ${fmt(truth)} (i.e. ${fmt(truth)} to 1).` }) : estimateRound({ prompt: `Odds converter: odds of <b>${fmt(p / (1 - p))} to 1</b> correspond to what <b>probability</b>?`, truth, tolerance: 0.1, min: 0, max: 1, step: 0.01, explain: `p = odds / (1 + odds) = ${fmt(p / (1 - p))} / ${fmt(1 + p / (1 - p))} = ${p}.` }); });
bespoke['W4.20'] = () => [predictRound({ prompt: 'Due or not: a fair roulette-style wheel (ignore the zero) has shown <b>red six times in a row</b>. What is P(black on the next spin)?', truth: 0.5, tolerance: 0.2, trial: () => (R() < 0.5 ? 1 : 0), explain: 'Black is not “due”. Each spin is independent; the wheel does not remember. Betting more because a result is overdue is the gambler’s fallacy.' })];
bespoke['W4.21'] = () => repeat(3, () => { const real = repeat(30, () => (R() < 0.5 ? 'H' : 'T')); const fake = []; for (let i = 0; i < 30; i++) { const last = fake[i - 1], prev = fake[i - 2]; fake.push(last && last === prev ? (last === 'H' ? 'T' : 'H') : (R() < 0.5 ? 'H' : 'T')); } const run = (s) => { let b = 1, c = 1; for (let i = 1; i < s.length; i++) { c = s[i] === s[i - 1] ? c + 1 : 1; b = Math.max(b, c); } return b; }; const opts = shuffle([{ html: `<code>${real.join('')}</code>`, correct: true }, { html: `<code>${fake.join('')}</code>`, correct: false }]); return pickRound({ prompt: 'Real or fake flips: one sequence is 30 genuine coin flips, the other was typed by a person trying to look random. Which is <b>real</b>?', options: opts.map((o) => ({ ...o, why: `The real sequence has a longest run of ${run(real)}; the human-made one ${run(fake)}. Genuine randomness is clumpier than people expect: runs of 4–5 are normal in 30 flips.` })) }); });
bespoke['W4.22'] = () => repeat(2, () => quizRound({ prompt: 'Smaller circle: Linda is 31, outspoken and was active in social justice campaigns at university. Which is <b>more probable</b>?', choices: ['Linda is a bank teller', 'Linda is a bank teller and active in the feminist movement'], answer: 0, why: 'A conjunction (A and B) can never be more probable than A alone; the second circle sits inside the first. Vivid detail makes it feel likelier, which is the conjunction fallacy.' }));
bespoke['W4.23'] = () => repeat(2, () => { const pop = choice([1e6, 5e6, 1e7]), match = choice([1e-4, 1e-5, 1e-6]); const truth = pop * match; return estimateRound({ prompt: `Courtroom flip: a DNA profile matches <b>1 in ${(1 / match).toLocaleString()}</b> people. The city has <b>${pop.toLocaleString()}</b> residents. Roughly how many <b>innocent</b> people would match by chance?`, truth, tolerance: 0.5 * truth, min: 0, max: Math.max(20, truth * 3), step: 1, explain: `${pop.toLocaleString()} × ${match} ≈ ${truth} matches. Saying “1 in ${(1 / match).toLocaleString()} chance the defendant is innocent” swaps P(match | innocent) for P(innocent | match): the prosecutor's fallacy.` }); });
bespoke['W4.24'] = () => [predictRound({ prompt: 'Three doors: a car is behind one of three doors. You pick one; the host, who knows where the car is, opens a different door showing a goat and offers a switch. P(win if you <b>switch</b>)?', truth: 2 / 3, tolerance: 0.2, trial: () => { const car = randInt(0, 2), pick = randInt(0, 2); return car !== pick ? 1 : 0; }, explain: 'Your first pick is right 1/3 of the time; switching wins exactly when it was wrong, 2/3 of the time. The host’s reveal moves probability to the remaining door, not to yours.' })];
bespoke['W4.25'] = () => repeat(2, () => { const n = choice([10, 15, 23, 30, 40]); let q = 1; for (let i = 0; i < n; i++) q *= (365 - i) / 365; return predictRound({ prompt: `Party match: <b>${n}</b> people at a party. P(at least two share a birthday)?`, truth: 1 - q, tolerance: 0.2, trial: () => { const seen = new Set(); for (let i = 0; i < n; i++) { const b = randInt(1, 365); if (seen.has(b)) return 1; seen.add(b); } return 0; }, explain: `There are ${n * (n - 1) / 2} pairs to match, not one. P(all different) = 365/365 × 364/365 × … = ${fmt(q, 3)}, so P(a match) = ${fmt(1 - q, 3)}.` }); });

/* =========================== World 5: Distribution Delta =========================== */
bespoke['W5.01'] = () => repeat(3, () => { const n = randInt(4, 6); let w = repeat(n, () => randInt(1, 6)); const tot = S.sum(w); const probs = w.map((x) => x / tot); const hide = randInt(0, n - 1); return estimateRound({ prompt: `Bar probabilities: this PMF has one bar missing (value <b>${hide + 1}</b>). All probabilities must sum to 1. What is P(X = ${hide + 1})?`, view: barChart(probs.map((p, i) => ({ label: String(i + 1), value: i === hide ? 0 : +p.toFixed(2) })), { height: 180, highlight: [hide] }), truth: probs[hide], tolerance: 0.08, min: 0, max: 1, step: 0.01, explain: `1 − (sum of the others ${fmt(1 - probs[hide], 2)}) = ${fmt(probs[hide], 2)}.` }); });
bespoke['W5.02'] = () => repeat(3, () => { const a = +(R() * 2 - 2.5).toFixed(1), b = +(a + 0.5 + R() * 2).toFixed(1); const truth = S.normalCdf(b) - S.normalCdf(a); return estimateRound({ prompt: `Area under: for a standard normal curve, what is P(<b>${a} < Z < ${b}</b>)? The shaded area is the probability.`, view: curvePlot([{ fn: (x) => S.normalPdf(x) }], { shade: [a, b], height: 200 }), truth, tolerance: 0.12, min: 0, max: 1, step: 0.01, explain: `Φ(${b}) − Φ(${a}) = ${fmt(S.normalCdf(b), 3)} − ${fmt(S.normalCdf(a), 3)} = ${fmt(truth, 3)}. For a continuous variable, probability is area, and a single point has zero area.` }); });
bespoke['W5.03'] = () => repeat(3, () => { const n = 6, p = choice([0.3, 0.5, 0.6]); const pm = Array.from({ length: n + 1 }, (_, k) => S.binomPmf(k, n, p)); const k = randInt(1, 4); const truth = S.sum(pm.slice(0, k + 1)); return estimateRound({ prompt: `Climb to one: the bars show P(X = k) for X ~ Binomial(${n}, ${p}). What is the CDF value <b>F(${k}) = P(X ≤ ${k})</b>?`, view: barChart(pm.map((v, i) => ({ label: String(i), value: +v.toFixed(2) })), { height: 180, highlight: pm.map((_, i) => i).filter((i) => i <= k) }), truth, tolerance: 0.1, min: 0, max: 1, step: 0.01, explain: `Add the highlighted bars: ${fmt(truth, 3)}. The CDF climbs from 0 to 1 and never goes down.` }); });
bespoke['W5.04'] = () => [predictRound({ prompt: 'Fair or loaded: on a fair six-sided die every face has the same probability. P(rolling a <b>6</b>)?', truth: 1 / 6, tolerance: 0.1, trial: () => (randInt(1, 6) === 6 ? 1 : 0), explain: 'Discrete uniform: k equally likely outcomes each have probability 1/k = 1/6 ≈ 0.167. Watch the running proportion settle there.' })];
bespoke['W5.05'] = () => repeat(3, () => { const a = randInt(0, 10), b = a + randInt(5, 20); const c = +(a + R() * (b - a)).toFixed(1); const truth = (c - a) / (b - a); return estimateRound({ prompt: `Flat river: a bus arrives at a uniformly random time between <b>${a}</b> and <b>${b}</b> minutes. P(it arrives before <b>${c}</b> minutes)?`, view: curvePlot([{ fn: (x) => (x >= a && x <= b ? 1 / (b - a) : 0) }], { domain: [a - 2, b + 2], shade: [a, c], height: 160 }), truth, tolerance: 0.1, min: 0, max: 1, step: 0.01, explain: `Width of the shaded piece over total width: (${c} − ${a}) / (${b} − ${a}) = ${fmt(truth, 3)}.` }); });
bespoke['W5.06'] = () => repeat(3, () => { const p = choice([0.1, 0.3, 0.5, 0.7, 0.9]); return estimateRound({ prompt: `One flip: a Bernoulli trial succeeds with probability <b>${p}</b>. What is its <b>variance</b> p(1 − p)? (Where is uncertainty highest?)`, truth: p * (1 - p), tolerance: 0.06, min: 0, max: 0.3, step: 0.005, explain: `${p} × ${fmt(1 - p)} = ${fmt(p * (1 - p), 3)}. Variance peaks at p = 0.5 (0.25) and vanishes when the outcome is certain.` }); });
bespoke['W5.07'] = () => repeat(2, () => { const n = randInt(5, 10), p = choice([0.5, 0.6, 0.7, 0.8]), k = randInt(Math.floor(n * p) - 1, Math.ceil(n * p) + 1); const truth = S.binomPmf(k, n, p); return predictRound({ prompt: `Free throws: a player hits <b>${pct(p)}</b> of free throws. In <b>${n}</b> independent throws, P(<b>exactly ${k}</b> hits)?`, truth, tolerance: 0.1, trial: () => (repeat(n, () => (R() < p ? 1 : 0)).reduce((s, x) => s + x, 0) === k ? 1 : 0), explain: `Binomial: C(${n}, ${k}) · ${p}^${k} · ${fmt(1 - p)}^${n - k} = ${fmt(truth, 3)}.` }); });
bespoke['W5.08'] = () => repeat(2, () => { const p = choice([0.1, 0.2, 0.25, 0.5]); return predictRound({ prompt: `Until first success: each attempt succeeds with probability <b>${p}</b>. On average, how many attempts <b>until (and including) the first success</b>?`, truth: 1 / p, tolerance: 0.35 / p, trial: () => { let k = 1; while (R() >= p) k++; return k; }, min: 1, max: 20, step: 0.1, label: 'Average attempts so far', explain: `Geometric distribution: E[X] = 1/p = ${fmt(1 / p)}. Waiting is memoryless: a long dry spell does not make success closer.` }); });
bespoke['W5.09'] = () => repeat(2, () => { const p = choice([0.2, 0.3, 0.5]), r = choice([2, 3]); return predictRound({ prompt: `Three hires: each candidate is suitable with probability <b>${p}</b>. Expected number of interviews to find <b>${r}</b> suitable candidates?`, truth: r / p, tolerance: 0.3 * r / p, trial: () => { let k = 0, s = 0; while (s < r) { k++; if (R() < p) s++; } return k; }, min: 1, max: 30, step: 0.1, label: 'Average interviews so far', explain: `Negative binomial: E = r/p = ${r}/${p} = ${fmt(r / p)}, i.e. ${r} geometric waits added together.` }); });
bespoke['W5.10'] = () => repeat(2, () => { const N = 20, K = randInt(4, 8), n = 5, k = randInt(1, 3); const C = (a, b) => (b < 0 || b > a ? 0 : fact(a) / (fact(b) * fact(a - b))); const truth = C(K, k) * C(N - K, n - k) / C(N, n); return predictRound({ prompt: `Without replacement: a box has <b>${N}</b> tickets, <b>${K}</b> of them winners. Draw <b>${n}</b> without replacement. P(<b>exactly ${k}</b> winners)?`, truth, tolerance: 0.1, trial: () => { const box = shuffle([...Array(K).fill(1), ...Array(N - K).fill(0)]); return box.slice(0, n).reduce((s, x) => s + x, 0) === k ? 1 : 0; }, explain: `Hypergeometric: C(${K},${k})·C(${N - K},${n - k}) / C(${N},${n}) = ${fmt(truth, 3)}. Each draw changes the odds for the next, unlike the binomial.` }); });
const poisson = (l) => { const L = Math.exp(-l); let k = 0, p = 1; do { k++; p *= R(); } while (p > L); return k - 1; };
bespoke['W5.11'] = () => repeat(2, () => { const l = choice([1, 2, 3, 4]), k = randInt(0, l + 2); const truth = S.poissonPmf(k, l); return predictRound({ prompt: `Rare events: a help desk gets on average <b>${l}</b> calls per hour, independently and at random. P(<b>exactly ${k}</b> calls in the next hour)?`, truth, tolerance: 0.1, trial: () => (poisson(l) === k ? 1 : 0), explain: `Poisson: e^−λ λ^k / k! = ${fmt(truth, 3)} with λ = ${l}. Mean and variance both equal λ.` }); });
bespoke['W5.12'] = () => { const mu = randInt(40, 60), sg = randInt(4, 12); const d = normals(300, mu, sg); return [estimateRound({ prompt: 'Bell fit: estimate <b>μ</b>, the centre of this normal sample.', data: d, chart: 'hist', bins: 24, truth: mean(d), tolerance: 0.5 * sg, domain: [mu - 4 * sg, mu + 4 * sg], explain: `Sample mean ${fmt(mean(d))} (true μ = ${mu}).` }), estimateRound({ prompt: 'Bell fit: now estimate <b>σ</b>. About 95% of the bars sit within 2σ of the centre.', data: d, chart: 'hist', bins: 24, truth: sd(d), tolerance: 0.35 * sg, min: 0, max: 25, step: 0.1, domain: [mu - 4 * sg, mu + 4 * sg], explain: `Sample SD ${fmt(sd(d))} (true σ = ${sg}). The curve is fully described by μ and σ.` })]; };
bespoke['W5.13'] = () => repeat(3, () => { const k = choice([1, 2, 3, 1.5, 0.5]); const truth = 2 * S.normalCdf(k) - 1; return estimateRound({ prompt: `Shade the bell: what fraction of a normal distribution lies within <b>±${k} SD</b> of the mean?`, view: curvePlot([{ fn: (x) => S.normalPdf(x) }], { shade: [-k, k], height: 180 }), truth, tolerance: 0.1, min: 0, max: 1, step: 0.01, explain: `${fmt(truth, 3)}. The 68–95–99.7 rule: ±1 SD ≈ 68%, ±2 SD ≈ 95%, ±3 SD ≈ 99.7%.` }); });
bespoke['W5.14'] = () => repeat(3, () => { const z = +(R() * 5 - 2.5).toFixed(2); const truth = S.normalCdf(z); return estimateRound({ prompt: `Table dive: what is <b>P(Z < ${z})</b> for a standard normal Z? (Shaded area to the left.)`, view: curvePlot([{ fn: (x) => S.normalPdf(x) }], { shade: [-4, z], height: 180 }), truth, tolerance: 0.1, min: 0, max: 1, step: 0.01, explain: `Φ(${z}) = ${fmt(truth, 4)}. A z-table lists exactly these left-tail areas.` }); });
const tPdf = (x, df) => Math.exp(S.lgamma((df + 1) / 2) - S.lgamma(df / 2)) / Math.sqrt(df * Math.PI) * (1 + x * x / df) ** (-(df + 1) / 2);
bespoke['W5.15'] = () => repeat(3, () => { const df = choice([2, 3, 5]); const opts = shuffle([{ html: curvePlot([{ fn: (x) => tPdf(x, df) }], { height: 150, domain: [-5, 5] }), correct: true, why: `The t curve (here with ${df} degrees of freedom) has a lower peak and fatter tails than the normal, because estimating σ from a small sample adds uncertainty. As df grows it becomes the normal.` }, { html: curvePlot([{ fn: (x) => S.normalPdf(x) }], { height: 150, domain: [-5, 5] }), correct: false }]); return pickRound({ prompt: 'Fat tails: one curve is the standard normal, the other is a t distribution with few degrees of freedom. Which is the <b>t</b>?', options: opts }); });
bespoke['W5.16'] = () => [(() => { const k = choice([2, 3, 4]); return samplerRound({ prompt: `Square and sum: each “sample” is ${k} standard-normal draws; the statistic is the <b>sum of their squares</b>. Build its distribution.`, population: normals(2000, 0, 1), sampleSize: k, stat: (s) => S.sum(s.map((z) => z * z)), statName: 'sum of squares', minDraws: 100, question: { prompt: `What is the <b>mean</b> of this chi-square distribution with ${k} degrees of freedom?`, truth: k, tolerance: 1.2, min: 0, max: 10, explain: `A χ² with k degrees of freedom has mean k = ${k} (and variance 2k). It is right-skewed because squares cannot be negative.` } }); })()];
bespoke['W5.17'] = () => [samplerRound({ prompt: 'Ratio rapids: each “sample” is 10 draws; the statistic is the <b>variance of the first 5 ÷ variance of the last 5</b>. Both halves come from the same population, so the ratio should hover near 1.', population: normals(2000, 50, 10), sampleSize: 10, stat: (s) => variance(s.slice(0, 5)) / variance(s.slice(5)), statName: 'variance ratio (F)', minDraws: 100, question: { prompt: 'What is the <b>median</b> of your F ratios?', truth: (st) => median(st), tolerance: 0.5, min: 0, max: 5, explain: (st, t) => `Median ${fmt(t)}: near 1 but with a long right tail, since a ratio can be huge but never below 0. ANOVA compares a variance ratio to this F shape.` } })];
bespoke['W5.18'] = () => repeat(2, () => { const m = choice([2, 5, 10]), t = choice([1, 3, 5, 8]); const truth = Math.exp(-t / m); return predictRound({ prompt: `Waiting time: buses arrive at random with a mean gap of <b>${m}</b> minutes (exponential). P(you wait <b>more than ${t}</b> minutes)?`, truth, tolerance: 0.12, trial: () => (-m * Math.log(R()) > t ? 1 : 0), explain: `P(T > t) = e^(−t/mean) = e^(−${t}/${m}) = ${fmt(truth, 3)}. Memoryless: having already waited changes nothing.` }); });
bespoke['W5.19'] = () => repeat(2, () => { const ln = repeat(300, () => Math.exp(S.randNormal(3, 0.6))); const nm = normals(300, 40, 10); const left = ln.map((v) => 120 - v).filter((v) => v > 0); const opts = shuffle([{ html: histogram(ln, { height: 150, bins: 25 }), correct: true, why: 'Right-skewed data with a long upper tail (incomes, reaction times, city sizes) are often log-normal: take logs and the histogram becomes a symmetric bell.' }, { html: histogram(nm, { height: 150, bins: 25 }), correct: false }, { html: histogram(left, { height: 150, bins: 25 }), correct: false }]); return pickRound({ prompt: 'Log lens: which histogram would become <b>symmetric and bell-shaped after taking logarithms</b>?', options: opts }); });
bespoke['W5.20'] = () => repeat(3, () => { const a = randInt(1, 8), b = randInt(1, 8); const truth = a / (a + b); return estimateRound({ prompt: `Shape shifter: a Beta(<b>${a}</b>, <b>${b}</b>) distribution on [0, 1]. Estimate its <b>mean</b>.`, view: curvePlot([{ fn: (x) => x ** (a - 1) * (1 - x) ** (b - 1) }], { domain: [0, 1], height: 170 }), truth, tolerance: 0.1, min: 0, max: 1, step: 0.01, explain: `Mean = a / (a + b) = ${a}/${a + b} = ${fmt(truth, 3)}. Beta is the go-to distribution for an unknown probability, and it is the Bayesian prior for a proportion.` }); });
bespoke['W5.21'] = () => repeat(2, () => { const m = choice([2, 4, 5]); const r = 3; return predictRound({ prompt: `Third arrival: customers arrive at random with mean gap <b>${m}</b> minutes. Expected time until the <b>${r}rd</b> customer?`, truth: r * m, tolerance: 0.3 * r * m, trial: () => -m * Math.log(R()) - m * Math.log(R()) - m * Math.log(R()), min: 0, max: 40, step: 0.1, unit: ' min', label: 'Average wait so far', explain: `The sum of ${r} exponential waits is Gamma(shape ${r}, scale ${m}) with mean ${r}×${m} = ${r * m} minutes.` }); });
bespoke['W5.22'] = () => [(() => { const n = choice([4, 9, 16, 25]); const pop = Array.from({ length: 600 }, (_, i) => (i % 6) + 1); const sig = sd(pop, false); return samplerRound({ prompt: `Dice avalanche: the population is a flat die (1–6). Draw samples of n = <b>${n}</b> and watch the <b>sample means</b> pile up into a bell, however flat the population.`, population: pop, sampleSize: n, minDraws: 100, question: { prompt: `The population SD is ${fmt(sig)}. What is the <b>SD of the sample means</b> (the standard error)?`, truth: sig / Math.sqrt(n), tolerance: 0.3 * sig / Math.sqrt(n), min: 0, max: 2, explain: (st, t) => `σ/√n = ${fmt(sig)}/√${n} = ${fmt(t)}; your simulated SD was ${fmt(sd(st))}. That is the central limit theorem: means are normal-ish with spread shrinking like 1/√n.` } }); })()];
const qq = (d) => { const s = [...d].sort((a, b) => a - b); const n = s.length; const xs = s.map((_, i) => S.normalInv((i + 0.5) / n)); return scatter(xs, s, { height: 170, xLabel: 'theoretical z', yLabel: 'sample' }); };
bespoke['W5.23'] = () => repeat(3, () => { const nm = normals(80, 50, 10), sk = skewed(80, 30, 0.6), hv = repeat(80, () => 50 + 10 * S.randNormal() / Math.sqrt((S.randNormal() ** 2 + S.randNormal() ** 2) / 2)); const opts = shuffle([{ html: qq(nm), correct: true, why: 'A Q–Q plot compares sample quantiles with normal quantiles: points on a straight line mean “normal enough”. A curve bending up at the right signals right skew; an S shape signals heavy tails.' }, { html: qq(sk), correct: false }, { html: qq(hv), correct: false }]); return pickRound({ prompt: 'Straight line check: which Q–Q plot comes from <b>normally distributed</b> data?', options: opts }); });
bespoke['W5.24'] = () => repeat(2, () => { const d = repeat(300, () => Math.exp(S.randNormal(3, 0.7))); return quizRound({ prompt: `Dial the power: this histogram is strongly right-skewed. Which transformation is most likely to make it roughly symmetric?${histogram(d, { height: 160, bins: 30 })}`, choices: ['Take the logarithm', 'Square each value', 'Take the exponential', 'Add 100 to each value'], answer: 0, why: 'Log (or square root) compresses the long right tail. Squaring or exponentiating stretches it further; adding a constant changes nothing about the shape.' }); });

/* =========================== World 6: Sampling Sea =========================== */
const SAMPLING = [
  { text: 'Number every student 1–2,000 and use a random-number generator to pick 100.', answer: 'Simple random sampling', why: 'Every set of 100 has the same chance: simple random sampling.' },
  { text: 'Split the school into year groups, then randomly pick 20 pupils from each year.', answer: 'Stratified sampling', why: 'Divide into homogeneous strata and sample within each: stratified.' },
  { text: 'Randomly choose 5 of the 40 classrooms and survey everyone inside them.', answer: 'Cluster sampling', why: 'Whole groups (clusters) are chosen and fully surveyed: cluster sampling.' },
  { text: 'Pick a random start, then survey every 25th person on the alphabetical list.', answer: 'Systematic sampling', why: 'Fixed interval from a random start: systematic sampling.' },
  { text: 'Interview whoever walks past the library entrance at lunchtime.', answer: 'Convenience sampling', why: 'Chosen because they are easy to reach: convenience sampling, prone to bias.' },
  { text: 'Post a poll on the website and count whoever chooses to answer.', answer: 'Voluntary response', why: 'People self-select; strong opinions over-respond: voluntary response bias.' },
  { text: 'Divide customers by region and randomly sample proportionally from each region.', answer: 'Stratified sampling', why: 'Strata by region with random sampling inside each.' },
  { text: 'Randomly select 10 villages and interview every household in them.', answer: 'Cluster sampling', why: 'Clusters are geographic; everyone in chosen clusters is included.' },
  { text: 'Ask your friends and have them ask their friends until you reach 200 responses.', answer: 'Snowball sampling', why: 'Referral chains: snowball sampling, a non-probability method for hidden populations.' },
  { text: 'Deliberately pick the 15 experts you think know the most.', answer: 'Purposive (judgement) sampling', why: 'Units are hand-picked by judgement: purposive sampling.' },
  { text: 'Recruit until you have 50 men and 50 women, taking whoever comes first.', answer: 'Quota sampling', why: 'Fixed quotas filled non-randomly: quota sampling.' },
];
const samplingRound = () => scenarioPick('Which <b>sampling method</b> is this?', SAMPLING, 5);
for (const id of ['W6.02', 'W6.03', 'W6.04', 'W6.06']) bespoke[id] = () => repeat(5, samplingRound);
bespoke['W6.01'] = () => [samplerRound({ prompt: 'Lucky net: the lake holds 400 fish. Cast nets of n = 10 and watch where the sample means land.', population: skewed(400, 25, 0.4), sampleSize: 10, minDraws: 50, question: { prompt: 'On average, where do your sample means sit? Give the <b>mean of the sample means</b>.', truth: (st) => mean(st), tolerance: 2, min: 10, max: 50, explain: (st, t) => `Mean of sample means ${fmt(t)}, which hugs the population mean: random sampling is unbiased, and individual samples wobble around the truth rather than leaning away from it.` } })];
bespoke['W6.05'] = () => [multiPickRound({ prompt: 'Who showed up: flag every sampling plan likely to give a <b>biased</b> picture of the whole population.', items: shuffle([
  { html: 'Estimate city opinion on a new tax by polling people at an anti-tax rally.', flaw: true, why: 'Rally-goers are a convenience sample with extreme views.' },
  { html: 'Measure average commute time by asking listeners of a drive-time radio show to call in.', flaw: true, why: 'Voluntary response from drivers only.' },
  { html: 'Estimate the share of defective chips by testing 50 picked by random number from the batch.', flaw: false, why: '' },
  { html: 'Rate a restaurant using only the online reviews customers chose to leave.', flaw: true, why: 'Reviewers self-select; the furious and the delighted dominate.' },
  { html: 'Survey household income by phoning random landline numbers at 2 pm on weekdays.', flaw: true, why: 'Convenient for the pollster, but reaches mainly retired or non-working people.' },
  { html: 'Pick 30 pupils with a random number table from the full school roll.', flaw: false, why: '' },
]) })];
const FRAME = [
  { text: 'A phone poll of voters uses the landline directory.', answer: 'Mobile-only and ex-directory households', why: 'They are missing from the frame, so they can never be sampled: coverage error.' },
  { text: 'An online survey of the elderly about loneliness.', answer: 'Older people without internet access', why: 'The frame (internet users) does not cover them, and they may be the loneliest.' },
  { text: 'A survey of a city’s residents uses the electoral roll.', answer: 'Non-citizens and unregistered residents', why: 'The electoral roll under-covers them.' },
  { text: 'An airline emails satisfaction surveys to its frequent-flyer members.', answer: 'Occasional passengers', why: 'Members are a subset; occasional flyers are not in the frame.' },
];
bespoke['W6.07'] = () => repeat(3, () => scenarioPick('Missing from the list: who is <b>left out of the sampling frame</b>?', FRAME, 4));
const WOBBLE = [['Two random polls of 1,000 people give 51% and 49% for the same candidate.', 'Sampling error (random wobble)'], ['A poll of magazine subscribers overstates support for the magazine’s favourite party.', 'Sampling bias (systematic lean)'], ['Ten random samples of 20 fish have means from 24 cm to 28 cm around a true 26 cm.', 'Sampling error (random wobble)'], ['Measuring fish only near the shore, where the small ones live.', 'Sampling bias (systematic lean)'], ['A larger sample would shrink this.', 'Sampling error (random wobble)'], ['A larger sample would NOT fix this; it would just be confidently wrong.', 'Sampling bias (systematic lean)']];
bespoke['W6.08'] = () => repeat(4, () => classify('Wobble or lean?', WOBBLE.map(([text, answer]) => ({ text, answer, why: answer.startsWith('Sampling error') ? 'Random variation between samples shrinks with sample size.' : 'A systematic tilt from how units were chosen; more data does not help.' })), ['Sampling error (random wobble)', 'Sampling bias (systematic lean)']));
bespoke['W6.09'] = () => repeat(3, () => scenarioPick('Who answered? What is the likely effect of the <b>non-response</b>?', [
  { text: 'A 12% response rate to a survey on job satisfaction; the unhappy are more likely to vent.', answer: 'Satisfaction is underestimated', why: 'If the dissatisfied respond more, the sample leans unhappy.' },
  { text: 'A course-evaluation form completed mostly by students who attended every lecture.', answer: 'Ratings are overestimated', why: 'Regular attenders tend to like the course more.' },
  { text: 'A health survey where the sick are too unwell to reply.', answer: 'Illness rates are underestimated', why: 'Those missing are the ones with the condition.' },
  { text: 'Follow-up calls raise the response rate from 20% to 80%.', answer: 'Non-response bias is reduced', why: 'Chasing non-responders makes the sample more representative.' },
], 4));
bespoke['W6.10'] = () => [(() => { const n = choice([5, 10, 25]); const pop = normals(500, 50, 12); const sig = sd(pop, false); return samplerRound({ prompt: `Many nets: cast nets of n = <b>${n}</b> from this population and build the <b>sampling distribution of the mean</b>.`, population: pop, sampleSize: n, minDraws: 100, question: { prompt: 'How wide is it? Give the <b>SD of the sample means</b>.', truth: sig / Math.sqrt(n), tolerance: 0.3 * sig / Math.sqrt(n), min: 0, max: 15, explain: (st, t) => `σ/√n = ${fmt(sig)}/√${n} = ${fmt(t)} (you observed ${fmt(sd(st))}). Bigger nets, tighter distribution.` } }); })()];
bespoke['W6.11'] = () => repeat(3, () => { const s = randInt(5, 30), n = choice([4, 9, 16, 25, 36, 64, 100]); return estimateRound({ prompt: `Shrink by root n: SD = <b>${s}</b>, sample size n = <b>${n}</b>. What is the <b>standard error of the mean</b>?`, truth: s / Math.sqrt(n), tolerance: 0.25 * s / Math.sqrt(n) + 0.2, min: 0, max: s, step: 0.05, explain: `SE = σ/√n = ${s}/√${n} = ${fmt(s / Math.sqrt(n))}. Quadrupling n only halves the SE.` }); });
bespoke['W6.12'] = () => [(() => { const p = choice([0.3, 0.5, 0.6]), n = choice([25, 50, 100]); const pop = Array.from({ length: 1000 }, (_, i) => (i < p * 1000 ? 1 : 0)); return samplerRound({ prompt: `Poll wobble: ${pct(p)} of this population say yes (1). Poll n = <b>${n}</b> at a time and watch the sample proportions.`, population: pop, sampleSize: n, statName: 'sample proportion', minDraws: 100, question: { prompt: 'Give the <b>SD of the sample proportions</b>.', truth: Math.sqrt(p * (1 - p) / n), tolerance: 0.3 * Math.sqrt(p * (1 - p) / n), min: 0, max: 0.2, explain: (st, t) => `√(p(1−p)/n) = √(${p}×${fmt(1 - p)}/${n}) = ${fmt(t, 3)}; observed ${fmt(sd(st), 3)}.` } }); })()];
bespoke['W6.13'] = () => repeat(3, () => { const mu = randInt(40, 60); const d = intsNormal(randInt(8, 15), mu, 8, 10, 90); return est(`Best guess: this is a sample from a population with unknown mean. Give your best single <b>point estimate</b> of the population mean.`, d, mean, (dd) => 0.5 * sd(dd), { truthLabel: 'x̄', explain: (t) => `The sample mean ${fmt(t)} is the natural point estimate (the hidden population mean was ${mu}). A single number carries no sense of its own uncertainty; that is what intervals add.` }); });
bespoke['W6.14'] = () => repeat(3, () => { const s = randInt(5, 20), n = choice([16, 25, 36, 64, 100]); const h = 1.96 * s / Math.sqrt(n); return estimateRound({ prompt: `Net caster: σ = <b>${s}</b> (known), n = <b>${n}</b>, sample mean 50. How far should a <b>95% confidence interval</b> reach on each side of 50 (its half-width)?`, truth: h, tolerance: 0.3 * h, min: 0, max: 15, step: 0.05, explain: `z × σ/√n = 1.96 × ${s}/√${n} = ${fmt(h)}. Interval: ${fmt(50 - h)} to ${fmt(50 + h)}.` }); });
bespoke['W6.15'] = () => repeat(3, () => { const s = randInt(5, 20), n = choice([5, 8, 12, 20, 30]); const t = S.tInv(0.975, n - 1); const h = t * s / Math.sqrt(n); return estimateRound({ prompt: `Small net: sample SD s = <b>${s}</b> (σ unknown), n = <b>${n}</b>. Half-width of the <b>95% CI</b> for the mean, using t?`, truth: h, tolerance: 0.3 * h, min: 0, max: 25, step: 0.05, explain: `t(${n - 1}, 0.975) = ${fmt(t, 3)}, so ${fmt(t, 3)} × ${s}/√${n} = ${fmt(h)}. With z you would get ${fmt(1.96 * s / Math.sqrt(n))}: too narrow for a small sample.` }); });
bespoke['W6.16'] = () => repeat(3, () => { const n = choice([100, 400, 1000, 2500]), k = Math.round(n * (0.3 + R() * 0.4)); const p = k / n; const h = 1.96 * Math.sqrt(p * (1 - p) / n); return estimateRound({ prompt: `Poll bracket: <b>${k}</b> of <b>${n}</b> voters say yes (${pct(p)}). Half-width of the <b>95% CI</b> for the true proportion, in percentage points?`, truth: h * 100, tolerance: 0.3 * h * 100, min: 0, max: 12, step: 0.1, unit: ' pts', explain: `1.96 × √(p̂(1−p̂)/n) = 1.96 × √(${fmt(p, 2)}×${fmt(1 - p, 2)}/${n}) = ${fmt(h * 100, 1)} points.` }); });
bespoke['W6.17'] = () => repeat(3, () => { const E = choice([0.01, 0.02, 0.03, 0.05]); const n = Math.ceil((1.96 / E) ** 2 * 0.25); return estimateRound({ prompt: `Budget pollster: you want a 95% margin of error of <b>±${E * 100} points</b> for a proportion, with no prior guess (use p = 0.5). How many people must you poll?`, truth: n, tolerance: 0.35 * n, min: 0, max: 12000, step: 10, explain: `n = (1.96/E)² × 0.25 = (1.96/${E})² × 0.25 ≈ ${n.toLocaleString()}. Halving the margin quadruples the sample.` }); });
bespoke['W6.18'] = () => [predictRound({ prompt: 'Hundred nets: you take many samples (n = 15) from a normal population and build a 95% t-interval each time. What fraction of intervals <b>capture the true mean</b>?', truth: 0.95, tolerance: 0.1, trial: () => { const s = normals(15, 50, 10); const ci = S.meanCI(s); return ci.lo <= 50 && 50 <= ci.hi ? 1 : 0; }, trials: 600, explain: '“95% confidence” is a property of the method: in the long run 95% of such intervals contain the truth. Any single interval either does or does not; there is no 95% probability about it.' })];
bespoke['W6.19'] = () => [(() => { const smp = skewed(20, 20, 0.5); return samplerRound({ prompt: `Resample reef: you only have this one sample of n = ${smp.length}. Resample it <b>with replacement</b> (n = ${smp.length} each time) and watch the bootstrap distribution of the mean build.`, population: smp, sampleSize: smp.length, popLabel: 'Your single sample', minDraws: 100, question: { prompt: 'Give the <b>bootstrap standard error</b>: the SD of the resampled means.', truth: (st) => sd(st), tolerance: 0.3 * sd(smp) / Math.sqrt(smp.length) + 0.3, min: 0, max: 10, explain: (st, t) => `Bootstrap SE ${fmt(t)}; the formula s/√n gives ${fmt(sd(smp) / Math.sqrt(smp.length))}. The bootstrap needs no formula and works for medians, ratios, anything.` } }); })()];
bespoke['W6.20'] = () => [samplerRound({ prompt: 'Dart board (bias): the population is the numbers 1–100. Draw samples of n = 5 and use the <b>sample maximum</b> as an estimator of the population maximum.', population: Array.from({ length: 100 }, (_, i) => i + 1), sampleSize: 5, stat: (s) => Math.max(...s), statName: 'sample maximum', minDraws: 100, question: { prompt: 'The true maximum is 100. Give the <b>mean of your sample maxima</b>.', truth: (st) => mean(st), tolerance: 6, min: 50, max: 100, explain: (st, t) => `Average ${fmt(t)}: the estimator systematically undershoots (theory: 100 × 5/6 ≈ 83.3). That gap is <b>bias</b>: the darts cluster, but off-centre.` } })];
bespoke['W6.21'] = () => repeat(2, () => { const n = 12; const means = repeat(400, () => mean(normals(n, 50, 10))), meds = repeat(400, () => median(normals(n, 50, 10))); const opts = shuffle([{ html: `<b>Estimator A</b>${histogram(means, { domain: [38, 62], bins: 30, height: 140 })}`, correct: true, why: `A is the sample mean (SD ${fmt(sd(means))}), B the sample median (SD ${fmt(sd(meds))}). Both are unbiased for a normal population, but the mean wobbles less: it is more <b>efficient</b>.` }, { html: `<b>Estimator B</b>${histogram(meds, { domain: [38, 62], bins: 30, height: 140 })}`, correct: false }]); return pickRound({ prompt: 'Steady hand: two unbiased estimators of the same population centre, each computed on 400 samples of n = 12. Which is <b>more efficient</b> (lower variance)?', options: opts }); });
bespoke['W6.22'] = () => repeat(3, () => { const s = randInt(8, 25); const n1 = choice([25, 100]), n2 = n1 * 16; return estimateRound({ prompt: `Closing in: with σ = ${s}, the SE of the mean at n = ${n1} is ${fmt(s / Math.sqrt(n1))}. What is it at n = <b>${n2.toLocaleString()}</b>?`, truth: s / Math.sqrt(n2), tolerance: 0.3 * s / Math.sqrt(n2) + 0.1, min: 0, max: 5, step: 0.01, explain: `${s}/√${n2} = ${fmt(s / Math.sqrt(n2))}. A consistent estimator converges on the truth as n grows; 16× the data gives 4× the precision.` }); });
const dartboard = (bias, spread) => { const xs = repeat(15, () => bias + S.randNormal(0, spread)), ys = repeat(15, () => bias * 0.6 + S.randNormal(0, spread)); return scatter(xs, ys, { height: 150, domain: [-3, 3], range: [-3, 3] }); };
bespoke['W6.23'] = () => repeat(3, () => { const target = choice([[0, 0.3, 'low bias, low variance'], [0, 1, 'low bias, high variance'], [1.5, 0.3, 'high bias, low variance'], [1.5, 1, 'high bias, high variance']]); const all = [[0, 0.3, 'low bias, low variance'], [0, 1, 'low bias, high variance'], [1.5, 0.3, 'high bias, low variance'], [1.5, 1, 'high bias, high variance']]; return pickRound({ prompt: `Four dartboards: the bullseye is at (0, 0). Which board shows <b>${target[2]}</b>?`, options: shuffle(all.map(([b, s, name]) => ({ html: dartboard(b, s), correct: name === target[2], why: 'Bias is how far the cloud’s centre sits from the bullseye; variance is how scattered the darts are. An estimator can be wrong in either way, or both.' }))) }); });
bespoke['W6.24'] = () => repeat(3, () => { const N = choice([200, 500, 1000]), n = choice([50, 100, 150]), s = 10; const fpc = Math.sqrt((N - n) / (N - 1)); return estimateRound({ prompt: `Nearly everyone: population N = <b>${N}</b>, sample n = <b>${n}</b> without replacement, σ = 10. The naive SE is ${fmt(s / Math.sqrt(n))}. What is the SE <b>with the finite population correction</b>?`, truth: s / Math.sqrt(n) * fpc, tolerance: 0.25, min: 0, max: 2, step: 0.01, explain: `Multiply by √((N−n)/(N−1)) = ${fmt(fpc, 3)}: ${fmt(s / Math.sqrt(n) * fpc, 3)}. Sampling a large share of a small population leaves less to be uncertain about.` }); });
bespoke['W6.25'] = () => repeat(3, () => { const sw = choice([0.6, 0.7, 0.8]); const mw = randInt(40, 60), mm = randInt(40, 60); const raw = sw * mw + (1 - sw) * mm, truth = 0.5 * mw + 0.5 * mm; return estimateRound({ prompt: `Rebalance: the sample is <b>${pct(sw)} women</b> (mean score ${mw}) and ${pct(1 - sw)} men (mean ${mm}), but the population is 50/50. The raw sample mean is ${fmt(raw)}. What is the <b>post-stratified</b> estimate?`, truth, tolerance: 2, min: 35, max: 65, step: 0.1, explain: `Reweight to the population shares: 0.5 × ${mw} + 0.5 × ${mm} = ${fmt(truth)}.` }); });

/* =========================== World 7: Hypothesis Highlands =========================== */
const HYP = [
  { text: 'A factory claims its bulbs last 1,000 hours on average; you suspect less.', h0: 'μ = 1,000 hours', h1: 'μ < 1,000 hours (one-tailed)', tail: 'One-tailed (left)' },
  { text: 'A coin is suspected of being unfair in either direction.', h0: 'p = 0.5', h1: 'p ≠ 0.5 (two-tailed)', tail: 'Two-tailed' },
  { text: 'A tutor claims her students score higher than the national mean of 70.', h0: 'μ = 70', h1: 'μ > 70 (one-tailed)', tail: 'One-tailed (right)' },
  { text: 'Does a new fertiliser change yield (could be up or down)?', h0: 'μ_new = μ_old', h1: 'μ_new ≠ μ_old (two-tailed)', tail: 'Two-tailed' },
  { text: 'Is the defect rate below the contractual 2%?', h0: 'p = 0.02', h1: 'p < 0.02 (one-tailed)', tail: 'One-tailed (left)' },
];
bespoke['W7.01'] = () => repeat(4, () => { const it = choice(HYP); const opts = shuffle([...new Set(HYP.map((h) => h.h0))]).slice(0, 4); if (!opts.includes(it.h0)) opts[0] = it.h0; return quizRound({ prompt: `Write the null: which is the correct <b>H₀</b>?<br><span class="scenario">${esc(it.text)}</span>`, choices: opts, answer: opts.indexOf(it.h0), why: `H₀ states “no effect / no difference / the claim holds”, always with equality: ${it.h0}.` }); });
bespoke['W7.02'] = () => repeat(4, () => { const it = choice(HYP); const opts = shuffle([...new Set(HYP.map((h) => h.h1))]).slice(0, 4); if (!opts.includes(it.h1)) opts[0] = it.h1; return quizRound({ prompt: `Pick a side: which is the correct <b>H₁</b>?<br><span class="scenario">${esc(it.text)}</span>`, choices: opts, answer: opts.indexOf(it.h1), why: `H₁ is what you are trying to show, chosen before seeing the data: ${it.h1}.` }); });
bespoke['W7.03'] = () => repeat(3, () => { const mu0 = 50, xb = randInt(44, 56), s = randInt(5, 15), n = choice([9, 16, 25, 36]); const t = (xb - mu0) / (s / Math.sqrt(n)); return estimateRound({ prompt: `Signal to noise: H₀: μ = ${mu0}. Sample mean <b>${xb}</b>, SD <b>${s}</b>, n = <b>${n}</b>. What is the <b>t statistic</b>?`, truth: t, tolerance: 0.6, min: -6, max: 6, step: 0.05, explain: `t = (x̄ − μ₀)/(s/√n) = (${xb} − ${mu0})/(${s}/√${n}) = ${fmt(t)}. Signal (the gap) divided by noise (the standard error).` }); });
bespoke['W7.04'] = () => [(() => { const a = intsNormal(10, 52, 8, 30, 80), b = intsNormal(10, 46, 8, 30, 80); const pooled = [...a, ...b]; const obs = mean(a) - mean(b); return samplerRound({ prompt: `Shuffle court: group A mean ${fmt(mean(a))}, group B mean ${fmt(mean(b))}, observed difference <b>${fmt(obs)}</b>. Each “sample” shuffles the 20 labels and recomputes A − B, building the <b>null distribution</b>.`, population: pooled, sampleSize: 20, stat: () => { const sh = shuffle(pooled); return mean(sh.slice(0, 10)) - mean(sh.slice(10)); }, statName: 'shuffled difference', popLabel: 'All 20 values pooled', minDraws: 200, question: { prompt: `What fraction of shuffled differences are <b>at least as extreme</b> as ${fmt(obs)} in either direction? That is the p-value.`, truth: (st) => st.filter((d) => Math.abs(d) >= Math.abs(obs)).length / st.length, tolerance: 0.12, min: 0, max: 1, explain: (st, t) => `p ≈ ${fmt(t, 3)}. If labels did not matter, a gap this big would arise about ${pct(t)} of the time. Welch's t-test gives ${S.fmtP(S.welchT(a, b).p)}.` } }); })()];
bespoke['W7.05'] = () => repeat(3, () => { const al = choice([0.1, 0.05, 0.01, 0.001]); const z = S.normalInv(1 - al / 2); return estimateRound({ prompt: `Draw the line: for a two-tailed z-test at <b>α = ${al}</b>, how far out must |z| be to reject H₀ (the critical value)?`, view: curvePlot([{ fn: (x) => S.normalPdf(x) }], { shade: [z, 4], height: 170 }), truth: z, tolerance: 0.4, min: 0, max: 4, step: 0.01, explain: `Each tail holds α/2 = ${al / 2}: z = ${fmt(z, 3)}. α is the false-alarm rate you accept in advance.` }); });
bespoke['W7.06'] = () => repeat(4, () => { const it = choice(HYP); const opts = ['One-tailed (left)', 'One-tailed (right)', 'Two-tailed']; return quizRound({ prompt: `Which tail?<br><span class="scenario">${esc(it.text)}</span>`, choices: opts, answer: opts.indexOf(it.tail), why: `${it.tail}: ${it.h1}. Use one tail only when the direction was fixed before the data arrived.` }); });
bespoke['W7.07'] = () => [predictRound({ prompt: 'False alarm: both groups come from the <b>same</b> population (H₀ is true). You run a t-test at α = 0.05 each time. What fraction of tests wrongly reject H₀?', truth: 0.05, tolerance: 0.07, trial: () => (S.welchT(normals(10, 50, 10), normals(10, 50, 10)).p < 0.05 ? 1 : 0), trials: 600, explain: 'The Type I error rate equals α by construction: 5% of true nulls get rejected. Run enough tests and false alarms are guaranteed.' })];
bespoke['W7.08'] = () => [(() => { const n = choice([10, 20]), d = 0.5; const pw = S.powerTwoSample(d, n); return predictRound({ prompt: `Missed signal: the true effect is d = ${d} (half an SD). With n = <b>${n}</b> per group at α = 0.05, what fraction of studies <b>fail to detect it</b> (Type II error)?`, truth: 1 - pw, tolerance: 0.15, trial: () => (S.welchT(normals(n, 50 + 10 * d, 10), normals(n, 50, 10)).p < 0.05 ? 0 : 1), trials: 500, explain: `β ≈ ${fmt(1 - pw, 2)}; power = 1 − β ≈ ${fmt(pw, 2)}. Small studies miss real effects most of the time.` }); })()];
bespoke['W7.09'] = () => repeat(3, () => { const d = choice([0.2, 0.3, 0.5, 0.8]), n = choice([10, 20, 30, 50, 100, 200]); const pw = S.powerTwoSample(d, n); return estimateRound({ prompt: `Power dials: effect size d = <b>${d}</b>, n = <b>${n}</b> per group, α = 0.05, two groups. Estimate the <b>power</b>.`, truth: pw, tolerance: 0.15, min: 0, max: 1, step: 0.01, explain: `Power ≈ ${fmt(pw, 2)}. To reach 80% with d = ${d} you need about ${Math.ceil(2 * ((1.96 + 0.84) / d) ** 2)} per group.` }); });
