bespoke['W7.12'] = () => repeat(3, () => { const a = randInt(10, 60), b = randInt(10, 60), c = randInt(10, 60), d = randInt(10, 60); const or = (a * d) / (b * c); return estimateRound({ prompt: 'Cross product: estimate the <b>odds ratio</b> of disease for exposed vs unexposed.', view: `<table class="tbl"><tr><th></th><th>Disease</th><th>No disease</th></tr><tr><th>Exposed</th><td>${a}</td><td>${b}</td></tr><tr><th>Unexposed</th><td>${c}</td><td>${d}</td></tr></table>`, truth: or, tolerance: 0.35 * or + 0.1, min: 0, max: 8, step: 0.05, explain: `OR = (a·d)/(b·c) = (${a}×${d})/(${b}×${c}) = ${fmt(or)}. Odds among exposed ${fmt(a / b)} vs unexposed ${fmt(c / d)}.` }); });
bespoke['W7.13'] = () => repeat(3, () => { const r0 = choice([0.02, 0.05, 0.1, 0.2]), rr = choice([0.5, 0.6, 0.75, 0.8]); const r1 = r0 * rr; const arr = r0 - r1, nnt = 1 / arr; const which = choice(['nnt', 'arr']); return which === 'nnt' ? estimateRound({ prompt: `Headline converter: “drug cuts risk by ${pct(1 - rr)}!” Baseline risk ${pct(r0)}, treated risk ${pct(r1)}. How many people must be treated to prevent one event (<b>NNT</b>)?`, truth: nnt, tolerance: 0.35 * nnt, min: 1, max: 300, step: 1, explain: `ARR = ${pct(r0)} − ${fmt(r1 * 100, 1)}% = ${fmt(arr * 100, 1)} points; NNT = 1/ARR = ${fmt(nnt, 0)}. The relative ${pct(1 - rr)} sounds bigger than the absolute ${fmt(arr * 100, 1)} points.` }) : estimateRound({ prompt: `Headline converter: relative risk <b>${rr}</b> on a baseline risk of <b>${pct(r0)}</b>. What is the <b>absolute risk reduction</b>, in percentage points?`, truth: arr * 100, tolerance: 1.5, min: 0, max: 15, step: 0.1, unit: ' pts', explain: `Treated risk = ${rr} × ${pct(r0)} = ${fmt(r1 * 100, 1)}%; ARR = ${fmt(arr * 100, 1)} points.` }); });
bespoke['W7.14'] = () => repeat(3, () => { const df = choice([3, 5, 10, 20, 60]), al = choice([0.05, 0.01]); const t = S.tInv(1 - al / 2, df); return estimateRound({ prompt: `Border patrol: two-tailed t-test, df = <b>${df}</b>, α = <b>${al}</b>. What is the critical |t|?`, truth: t, tolerance: 0.4, min: 0, max: 7, step: 0.01, explain: `t(${df}; ${1 - al / 2}) = ${fmt(t, 3)}; the normal would give ${fmt(S.normalInv(1 - al / 2), 3)}. Fewer df push the border outward.` }); });
const groupView = (groups) => boxPlot(groups, { height: 60 + 50 * groups.length }) + `<div class="muted">${groups.map((g) => `${g.label}: n = ${g.data.length}, mean ${fmt(mean(g.data))}, SD ${fmt(sd(g.data))}`).join(' · ')}</div>`;
bespoke['W7.15'] = () => repeat(3, () => { const p0 = choice([0.5, 0.3, 0.2]), n = choice([50, 100, 200]); const k = Math.round(n * (p0 + S.randNormal(0, 0.08))); const ph = k / n; const z = (ph - p0) / Math.sqrt(p0 * (1 - p0) / n); const p = 2 * (1 - S.normalCdf(Math.abs(z))); return sigBetRound({ prompt: `Claim checker: a company claims <b>${pct(p0)}</b> of customers renew. In a random sample of ${n}, <b>${k}</b> renewed (${pct(ph)}). Two-tailed z-test for a proportion.`, view: barChart([{ label: 'claimed', value: +(p0 * 100).toFixed(0) }, { label: 'observed', value: +(ph * 100).toFixed(1) }], { height: 160, yLabel: '% renewing' }), result: { p, text: `z = (${fmt(ph, 3)} − ${p0}) / √(${p0}×${fmt(1 - p0)}/${n}) = ${fmt(z)}.` } }); });
