bespoke['W7.34'] = () => [(() => { const m = choice([10, 20, 30]); return predictRound({ prompt: `Twenty jelly beans: you test <b>${m}</b> colours of jelly bean for a link to acne. None has any effect. At α = 0.05, P(<b>at least one</b> colour comes out “significant”)?`, truth: 1 - 0.95 ** m, tolerance: 0.15, trial: () => (repeat(m, () => R() < 0.05).some(Boolean) ? 1 : 0), explain: `1 − 0.95^${m} = ${fmt(1 - 0.95 ** m, 2)}. Run enough tests and a false discovery becomes the expected outcome, which is why the green jelly bean made the headlines.` }); })()];
