function pvalSet() { const m = 6; const ps = shuffle([...repeat(randInt(2, 3), () => +(R() * 0.012).toFixed(3)), ...repeat(1, () => +(0.015 + R() * 0.03).toFixed(3)), ...repeat(2, () => +(0.1 + R() * 0.8).toFixed(2))]).slice(0, m).sort((a, b) => a - b); return ps; }
