// Multiple regression via normal equations (small k). Returns R².
function r2Multi(X, y) { const n = y.length, k = X.length; const A = Array.from({ length: k + 1 }, (_, i) => Array.from({ length: k + 1 }, (_, j) => S.sum(Array.from({ length: n }, (_, t) => (i ? X[i - 1][t] : 1) * (j ? X[j - 1][t] : 1))))); const b = Array.from({ length: k + 1 }, (_, i) => S.sum(Array.from({ length: n }, (_, t) => (i ? X[i - 1][t] : 1) * y[t]))); const beta = solve(A, b); const yhat = Array.from({ length: n }, (_, t) => beta[0] + S.sum(X.map((col, j) => beta[j + 1] * col[t]))); const my = mean(y); return 1 - S.sum(y.map((v, t) => (v - yhat[t]) ** 2)) / S.sum(y.map((v) => (v - my) ** 2)); }
function solve(A, b) { const n = b.length; const M = A.map((r, i) => [...r, b[i]]); for (let i = 0; i < n; i++) { let p = i; for (let r = i + 1; r < n; r++) if (Math.abs(M[r][i]) > Math.abs(M[p][i])) p = r; [M[i], M[p]] = [M[p], M[i]]; for (let r = 0; r < n; r++) if (r !== i) { const f = M[r][i] / M[i][i]; for (let c = i; c <= n; c++) M[r][c] -= f * M[i][c]; } } return M.map((r, i) => r[n] / r[i]); }
function coefMulti(X, y) { const n = y.length, k = X.length; const A = Array.from({ length: k + 1 }, (_, i) => Array.from({ length: k + 1 }, (_, j) => S.sum(Array.from({ length: n }, (_, t) => (i ? X[i - 1][t] : 1) * (j ? X[j - 1][t] : 1))))); const b = Array.from({ length: k + 1 }, (_, i) => S.sum(Array.from({ length: n }, (_, t) => (i ? X[i - 1][t] : 1) * y[t]))); return solve(A, b); }
bespoke['W8.23'] = () => repeat(2, () => { const n = 60; const z = normals(n, 50, 10); const x = z.map((v) => 0.8 * v + S.randNormal(0, 6)); const trueB = choice([0, 0.5]); const y = z.map((v, i) => 1.5 * v + trueB * x[i] + S.randNormal(0, 5)); const simple = S.linreg(x, y).slope; const adj = coefMulti([x, z], y)[1]; return estimateRound({ prompt: `Add the confounder: regressing y on x alone gives slope <b>${fmt(simple)}</b>. But z affects both x and y. Estimate the slope of x <b>after adjusting for z</b> (multiple regression with x and z).`, view: scatter(x, y, { height: 200, line: S.linreg(x, y), xLabel: 'x', yLabel: 'y' }), truth: adj, tolerance: 0.5, min: -1, max: 3, step: 0.05, explain: `Adjusted slope ${fmt(adj)} (the true causal effect was ${trueB}). The simple slope borrowed z’s effect because x and z move together.` }); });
