bespoke['W8.25'] = () => repeat(3, () => { const b1 = choice([1, 2, 3]), b3 = choice([-1.5, 1.5, 2, -2]); return estimateRound({ prompt: `Slope changer: ŷ = 10 + ${b1}·x + 4·G + ${b3}·(x × G), where G = 1 for group B, 0 for group A. What is the <b>slope of x for group B</b>?`, truth: b1 + b3, tolerance: 0.8, min: -4, max: 8, step: 0.1, explain: `For G = 1 the x terms are ${b1}·x + ${b3}·x = ${fmt(b1 + b3)}·x. The interaction term lets the slope differ by group; group A keeps slope ${b1}.` }); });
bespoke['W8.26'] = () => repeat(3, () => { const k = randInt(3, 6); return quizRound({ prompt: `Code the category: a predictor has <b>${k}</b> categories (e.g. ${['North', 'South', 'East', 'West', 'Centre', 'Island'].slice(0, k).join(', ')}). How many dummy (0/1) variables do you include, with an intercept in the model?`, choices: [String(k - 1), String(k), String(k + 1), '1'], answer: 0, why: `${k} − 1 = ${k - 1}. One category is the reference level absorbed by the intercept; each dummy coefficient is that category’s difference from the reference. Using all ${k} makes them perfectly collinear with the intercept.` }); });
bespoke['W8.27'] = () => repeat(2, () => { const xs = uniforms(40, 0, 10); const ys = xs.map((x) => 20 + 6 * x - 0.6 * x * x + S.randNormal(0, 2)); return quizRound({ prompt: `Bend the line: which model suits this scatter?${scatter(xs, ys, { height: 200, line: S.linreg(xs, ys) })}`, choices: ['Add a squared term: y = b₀ + b₁x + b₂x²', 'Keep the straight line; the fit is fine', 'Take the log of x', 'Remove the points at the edges'], answer: 0, why: 'The straight line underpredicts in the middle and overpredicts at the ends: a clear curve. A quadratic term (still a linear model in the coefficients) captures it.' }); });
bespoke['W8.28'] = () => repeat(3, () => { const b0 = choice([-4, -3, -2]), b1 = choice([0.5, 1, 1.5]); const x = randInt(0, 6); const p = 1 / (1 + Math.exp(-(b0 + b1 * x))); return estimateRound({ prompt: `S-curve: logistic model log-odds = ${b0} + ${b1}·x. What is the predicted <b>probability</b> when x = <b>${x}</b>?`, view: curvePlot([{ fn: (v) => 1 / (1 + Math.exp(-(b0 + b1 * v))) }], { domain: [-2, 10], height: 170 }), truth: p, tolerance: 0.12, min: 0, max: 1, step: 0.01, explain: `log-odds = ${fmt(b0 + b1 * x)}; p = 1/(1 + e^−${fmt(b0 + b1 * x)}) = ${fmt(p, 3)}. The S-curve keeps probabilities between 0 and 1.` }); });
bespoke['W8.29'] = () => repeat(3, () => { const b = choice([-0.7, -0.3, 0.2, 0.5, 0.9, 1.4]); return estimateRound({ prompt: `Exponentiate: a logistic coefficient is <b>${b}</b> per unit of x. What is the <b>odds ratio</b> per unit?`, truth: Math.exp(b), tolerance: 0.35 * Math.exp(b) + 0.1, min: 0, max: 5, step: 0.01, explain: `OR = e^${b} = ${fmt(Math.exp(b))}: the odds multiply by ${fmt(Math.exp(b))} for each unit increase in x${b > 0 ? '' : ' (a decrease)'}.` }); });
bespoke['W8.30'] = () => repeat(3, () => { const t = +(0.4 + R() * 1.4).toFixed(2); const sens = 1 - S.normalCdf(t, 1.5, 1), spec = S.normalCdf(t, 0, 1); const which = choice(['sensitivity', 'specificity']); const truth = which === 'sensitivity' ? sens : spec; return estimateRound({ prompt: `Threshold slider: healthy scores ~ N(0, 1), diseased scores ~ N(1.5, 1). You call “positive” when the score exceeds <b>${t}</b>. Estimate the <b>${which}</b>.`, view: curvePlot([{ fn: (v) => S.normalPdf(v, 0, 1), cls: 'alt' }, { fn: (v) => S.normalPdf(v, 1.5, 1) }], { domain: [-3, 5], shade: which === 'sensitivity' ? [t, 5] : [-3, t], lines: [{ v: t, cls: 'ref', label: 'threshold' }], height: 180 }) + '<div class="muted">Blue: healthy. Orange: diseased. Shaded region drawn on the curve that the question is about.</div>', truth, tolerance: 0.12, min: 0, max: 1, step: 0.01, explain: `Sensitivity = P(score > t | diseased) = ${fmt(sens, 3)}; specificity = P(score ≤ t | healthy) = ${fmt(spec, 3)}. Sliding the threshold trades one for the other; the ROC curve traces every trade-off.` }); });
bespoke['W8.31'] = () => repeat(2, () => { const degs = [1, 2, 3, 5, 9]; const base = choice([1, 2, 3]); const rows = degs.map((d) => { const train = +(3.2 - 0.35 * degs.indexOf(d) + R() * 0.1).toFixed(2); const test = +((d === base ? 2.3 : 2.3 + 0.5 * Math.abs(degs.indexOf(d) - degs.indexOf(base)) + (d > base ? 0.3 * (d - base) : 0)) + R() * 0.1).toFixed(2); return { d, train, test }; }); const best = rows.reduce((a, b) => (a.test < b.test ? a : b)).d; return quizRound({ prompt: `Wiggle trap: polynomial fits of increasing degree. Which degree should you ship?<table class="tbl"><tr><th>Degree</th>${rows.map((r) => `<td>${r.d}</td>`).join('')}</tr><tr><th>Train RMSE</th>${rows.map((r) => `<td>${r.train}</td>`).join('')}</tr><tr><th>Test RMSE</th>${rows.map((r) => `<td>${r.test}</td>`).join('')}</tr></table>`, choices: degs.map(String), answer: degs.indexOf(best), why: `Training error always falls as the model wiggles more; test error is what matters and it bottoms out at degree ${best}. Beyond that the model memorises noise: overfitting.` }); });
bespoke['W8.32'] = () => repeat(3, () => { const n = choice([50, 100, 200]), k = choice([5, 10]); const q = choice(['train', 'times']); return q === 'train' ? quizRound({ prompt: `Fold it: ${k}-fold cross-validation on n = ${n}. How many observations does each fold <b>train</b> on?`, choices: [String(n - n / k), String(n / k), String(n), String(n * (k - 1))], answer: 0, why: `Each fold holds out n/k = ${n / k} for testing and trains on the other ${n - n / k}. Every observation is tested exactly once, so the test estimate uses all the data without peeking.` }) : quizRound({ prompt: `Fold it: in ${k}-fold cross-validation, how many times does each observation appear in a <b>test</b> set?`, choices: ['1', String(k), String(k - 1), '0'], answer: 0, why: `Exactly once: the folds partition the data. Averaging the ${k} test errors gives an honest estimate of out-of-sample performance.` }); });
bespoke['W8.33'] = () => repeat(2, () => quizRound({ prompt: 'Shrink dial: you turn up the ridge penalty λ. What happens to the coefficients?', choices: ['They all shrink smoothly toward zero but none becomes exactly zero', 'Some become exactly zero', 'They grow to compensate', 'Only the intercept changes'], answer: 0, why: 'Ridge adds λ·Σβ² to the loss: it trades a little bias for much less variance, taming multicollinearity and overfitting, but keeps every predictor in play.' }));
bespoke['W8.34'] = () => repeat(2, () => quizRound({ prompt: 'Zero it out: you turn up the lasso penalty λ. What happens?', choices: ['Weak predictors are driven to exactly zero, performing variable selection', 'All coefficients shrink but stay nonzero', 'R² on the training data rises', 'Coefficients become unbiased'], answer: 0, why: 'Lasso penalises Σ|β|; the corners of that diamond-shaped constraint make exact zeros likely, so lasso both regularises and selects variables.' }));
bespoke['W8.35'] = () => repeat(3, () => { const ll1 = -randInt(180, 220), k1 = 3; const gain = randInt(1, 12); const ll2 = ll1 + gain, k2 = k1 + 3; const aic1 = 2 * k1 - 2 * ll1, aic2 = 2 * k2 - 2 * ll2; return quizRound({ prompt: `Pay for parameters: Model 1 has ${k1} parameters, log-likelihood ${ll1}. Model 2 adds 3 parameters and reaches log-likelihood ${ll2}. By AIC = 2k − 2·lnL, which wins?`, choices: ['Model 1', 'Model 2'], answer: aic1 <= aic2 ? 0 : 1, why: `AIC₁ = ${aic1}, AIC₂ = ${aic2}; lower is better. The extra fit (${gain}) must beat the price of the parameters (${2 * 3} AIC points). BIC charges ln(n) per parameter, a higher price.` }); });
bespoke['W8.36'] = () => [predictRound({ prompt: 'Noise miner: stepwise selection screens <b>15 pure-noise predictors</b>, keeping any with p < 0.05. P(the “final model” contains at least one noise predictor)?', truth: 1 - 0.95 ** 15, tolerance: 0.15, trial: () => (repeat(15, () => R() < 0.05).some(Boolean) ? 1 : 0), explain: `1 − 0.95¹⁵ = ${fmt(1 - 0.95 ** 15, 2)}. Stepwise selection is multiple testing in disguise; the surviving p-values and coefficients are biased upward.` })];
bespoke['W8.37'] = () => repeat(2, () => quizRound({ prompt: 'Two bands: at x = 60, the model gives a 95% <b>confidence interval</b> for the mean response and a 95% <b>prediction interval</b> for one new observation. Which is wider, and why?', choices: ['The prediction interval: it adds the scatter of individuals around the line', 'The confidence interval: estimating a mean is harder', 'They are equal', 'Depends on the sign of the slope'], answer: 0, why: 'The CI covers uncertainty about where the line is; the PI covers that plus the residual noise of a single new case, so it is always wider, and it does not shrink to zero with more data.' }));
bespoke['W8.38'] = () => repeat(2, () => { const a1 = [randInt(5, 15), 100], a2 = [randInt(60, 80), 100]; const b1 = [a1[0] + randInt(1, 4), 20], b2 = [a2[0] + randInt(1, 6), 180]; const nA = 200, nB = 200; const overallA = (a1[0] + a2[0]) / nA, overallB = (b1[0] + b2[0]) / nB; return quizRound({ prompt: `Reversal: two hospitals, mortality by surgery type.<table class="tbl"><tr><th></th><th>Hospital A</th><th>Hospital B</th></tr><tr><th>Hard cases</th><td>${a2[0]}/${a2[1]} (${pct(a2[0] / a2[1])})</td><td>${b2[0]}/${b2[1]} (${pct(b2[0] / b2[1])})</td></tr><tr><th>Easy cases</th><td>${a1[0]}/${a1[1]} (${pct(a1[0] / a1[1])})</td><td>${b1[0]}/${b1[1]} (${pct(b1[0] / b1[1])})</td></tr><tr><th>Overall</th><td>${a1[0] + a2[0]}/${nA} (${pct(overallA)})</td><td>${b1[0] + b2[0]}/${nB} (${pct(overallB)})</td></tr></table>Which hospital is safer?`, choices: ['A: it is better within each type of case; B only looks better overall because it takes mostly easy cases', 'B: its overall mortality is lower', 'Neither: the data are contradictory', 'The sample is too small to say'], answer: 0, why: `Simpson’s paradox. Case mix (a confounder) differs: A takes mostly hard cases. Compare like with like: within each stratum, A wins.` }); });
bespoke['W8.39'] = () => repeat(3, () => { const r = choice([0.3, 0.5, 0.7]), z = choice([1.5, 2, 2.5]); return estimateRound({ prompt: `Slump predictor: year-to-year performance correlates at r = <b>${r}</b>. A player was <b>${z} SD</b> above average this year. Predicted z-score next year?`, truth: r * z, tolerance: 0.5, min: -1, max: 3, step: 0.05, explain: `E[z₂ | z₁] = r × z₁ = ${r} × ${z} = ${fmt(r * z)}. Extreme performances are partly luck, and luck does not repeat: regression to the mean, no curse required.` }); });
bespoke['W8.40'] = () => repeat(2, () => quizRound({ prompt: 'Zoom in: across US states, those with more immigrants have higher average incomes. A journalist concludes immigrants earn more than natives. What is wrong?', choices: ['Ecological fallacy: a state-level correlation need not hold for individuals', 'Nothing; the inference is valid', 'The sample of states is too small', 'Income should be the x variable'], answer: 0, why: 'Group averages can correlate for reasons that have nothing to do with the individuals (immigrants may move to rich states). Individual-level data are needed for individual-level claims.' }));
bespoke['W8.41'] = () => repeat(3, () => { const b = choice([1, 2, 3]), rel = choice([0.5, 0.7, 0.9]); return estimateRound({ prompt: `Fuzzy x: the true slope of y on x is <b>${b}</b>, but x is measured with error so that only <b>${pct(rel)}</b> of its observed variance is real (reliability ${rel}). What slope will the regression on noisy x show?`, truth: b * rel, tolerance: 0.4, min: 0, max: 4, step: 0.05, explain: `Observed slope ≈ true slope × reliability = ${b} × ${rel} = ${fmt(b * rel)}. Measurement error in x attenuates (shrinks) the slope toward zero; error in y only adds noise.` }); });

/* =========================== World 9: Design Docks =========================== */
const ASSIGN = [
  { text: 'Researchers compare lung cancer rates in people who chose to smoke vs those who did not.', answer: 'Observational', why: 'Participants assigned themselves; confounders ride along.' },
  { text: 'Patients are randomly allocated to drug or placebo by computer.', answer: 'Experimental (randomised)', why: 'The researcher assigned treatment at random.' },
  { text: 'A survey records diet and later heart disease over 10 years.', answer: 'Observational', why: 'Nobody assigned diets; it was observed.' },
  { text: 'Farm plots are randomly given fertiliser A or B and yields compared.', answer: 'Experimental (randomised)', why: 'Random assignment of the treatment.' },
  { text: 'Schools that already use tablets are compared with schools that do not.', answer: 'Observational', why: 'Schools self-selected; richer schools may differ in many ways.' },
];
bespoke['W9.01'] = () => repeat(4, () => classify('Who assigned it? Is this study observational or experimental?', ASSIGN, ['Observational', 'Experimental (randomised)']));
bespoke['W9.02'] = () => [multiPickRound({ prompt: 'Build a trial: select every component that belongs in a well-designed <b>randomised controlled trial</b>.', items: shuffle([
  { html: 'Random allocation to treatment or control', flaw: true, why: 'Randomisation balances known and unknown confounders.' },
  { html: 'A control group receiving placebo or standard care', flaw: true, why: 'Without a comparison you cannot separate the treatment from time, attention and regression to the mean.' },
  { html: 'Blinding of participants and outcome assessors', flaw: true, why: 'Blinding stops expectations from colouring outcomes.' },
  { html: 'Let patients choose which arm they join', flaw: false, why: '' },
  { html: 'A pre-registered primary outcome and analysis plan', flaw: true, why: 'Fixing the outcome in advance prevents cherry-picking.' },
  { html: 'Drop participants who stop taking the drug from the analysis', flaw: false, why: '' },
  { html: 'A sample size justified by a power calculation', flaw: true, why: 'Otherwise the trial may be unable to detect a real effect.' },
]), submitText: 'Launch the trial' })];
bespoke['W9.03'] = () => repeat(2, () => quizRound({ prompt: 'What would have happened: 100 people with colds take a remedy; 90% recover within a week. What is missing before you can credit the remedy?', choices: ['A control group: most colds resolve in a week anyway', 'A larger sample', 'A longer follow-up', 'Measuring the dose more precisely'], answer: 0, why: 'The control group estimates the counterfactual: what would have happened without the remedy. Natural recovery, placebo effects and regression to the mean all hide inside “90% recovered”.' }));
bespoke['W9.04'] = () => repeat(3, () => { const plac = randInt(15, 35), drug = plac + randInt(0, 20); return estimateRound({ prompt: `Sugar pill: in a blinded trial, <b>${drug}%</b> improved on the drug and <b>${plac}%</b> improved on placebo. What is the drug's <b>own</b> effect, in percentage points?`, truth: drug - plac, tolerance: 4, min: 0, max: 40, step: 1, unit: ' pts', explain: `${drug} − ${plac} = ${drug - plac} points. The placebo arm absorbs expectation, attention and natural recovery; only the difference belongs to the drug.` }); });
bespoke['W9.05'] = () => repeat(3, () => { const items = [['Only the participants do not know their group', 'Single-blind'], ['Neither participants nor the staff assessing outcomes know', 'Double-blind'], ['Participants, staff and the statisticians analysing data all do not know', 'Triple-blind'], ['Everyone knows who got what', 'Open-label']]; const [text, ans] = choice(items); const opts = items.map((i) => i[1]); return quizRound({ prompt: `Who knows?<br><span class="scenario">${text}</span>`, choices: opts, answer: opts.indexOf(ans), why: `${ans}. Each extra layer of blinding closes one route for expectations to leak into the result.` }); });
bespoke['W9.06'] = () => [predictRound({ prompt: 'Fair shuffle: 20 volunteers, 10 of them women, are randomly split into two groups of 10. On average, how many women end up in group A?', truth: 5, tolerance: 1.5, trial: () => shuffle([...Array(10).fill(1), ...Array(10).fill(0)]).slice(0, 10).reduce((s, x) => s + x, 0), min: 0, max: 10, step: 0.1, label: 'Average women in group A', explain: 'Randomisation balances every characteristic on average, measured or not. Any single shuffle can be lopsided (that is why big trials, or blocking, help).' })];
bespoke['W9.07'] = () => repeat(2, () => quizRound({ prompt: 'Block party: you expect sex to strongly affect the outcome and have only 20 participants. Best design?', choices: ['Randomise separately within men and within women (blocking / stratified randomisation)', 'Simple randomisation and hope', 'Put all men in treatment and all women in control', 'Exclude one sex'], answer: 0, why: 'Blocking guarantees balance on a known important factor and removes its variation from the error term, giving more power with the same n.' }));
bespoke['W9.08'] = () => repeat(2, () => quizRound({ prompt: 'Perfect partners: to test a shoe sole material, each participant wears material A on one foot and B on the other, randomly assigned. Why is this powerful?', choices: ['Each person is their own control, removing person-to-person variation', 'It doubles the sample size', 'It removes the need for randomisation', 'It eliminates measurement error'], answer: 0, why: 'A matched-pairs design compares within pairs (or within people), so the huge between-person differences cancel out. Analyse the differences (paired test).' }));
bespoke['W9.09'] = () => repeat(3, () => { const a = randInt(2, 4), b = randInt(2, 3); return estimateRound({ prompt: `Cell filler: a factorial design with factor A at <b>${a}</b> levels and factor B at <b>${b}</b> levels. How many treatment combinations (cells)?`, truth: a * b, tolerance: 1.5, min: 1, max: 16, step: 1, explain: `${a} × ${b} = ${a * b} cells. One experiment tests both main effects and their interaction, more efficiently than two separate studies.` }); });
bespoke['W9.10'] = () => repeat(2, () => quizRound({ prompt: 'Follow the ships: 5,000 smokers and 5,000 non-smokers, free of disease, are followed for 20 years and new lung-cancer cases counted. What design is this, and what can it estimate directly?', choices: ['Prospective cohort study; it can estimate relative risk', 'Case-control study; it estimates the odds ratio only', 'Cross-sectional study; it estimates prevalence', 'Randomised trial; it estimates causal effect'], answer: 0, why: 'Exposure first, outcomes later, in a defined group: a cohort. Because incidence is observed in both groups, risk (and relative risk) is directly estimable.' }));
bespoke['W9.11'] = () => repeat(3, () => { const a = randInt(40, 80), b = 100 - a, c = randInt(20, 50), d = 100 - c; const or = (a * d) / (b * c); return estimateRound({ prompt: `Look back: 100 cases of a disease and 100 healthy controls were asked about past exposure.<table class="tbl"><tr><th></th><th>Cases</th><th>Controls</th></tr><tr><th>Exposed</th><td>${a}</td><td>${c}</td></tr><tr><th>Unexposed</th><td>${b}</td><td>${d}</td></tr></table>Estimate the <b>odds ratio</b>. (Risk cannot be computed here: you chose how many cases to include.)`, truth: or, tolerance: 0.35 * or + 0.2, min: 0, max: 10, step: 0.05, explain: `OR = (${a}×${d})/(${b}×${c}) = ${fmt(or)}. Case-control designs fix the outcome counts, so the OR is the natural measure; it approximates RR when the disease is rare.` }); });
bespoke['W9.12'] = () => repeat(2, () => quizRound({ prompt: 'Snapshot: a one-off survey finds that people who exercise more report less depression. What can it NOT tell you?', choices: ['Which came first: maybe depression reduces exercise', 'The prevalence of depression in the sample', 'Whether the two are associated', 'The proportion who exercise'], answer: 0, why: 'Cross-sectional data measure exposure and outcome at the same moment, so temporal order (and therefore direction of any causal arrow) is unknown.' }));
bespoke['W9.13'] = () => repeat(2, () => quizRound({ prompt: 'Same people, new year: the same 2,000 households are surveyed every year for a decade. What advantage does this panel design have over a fresh sample each year?', choices: ['It tracks change within individuals, separating ageing from cohort differences', 'It is cheaper', 'It removes the need for weighting', 'It avoids attrition'], answer: 0, why: 'Longitudinal panels see within-person change, which repeated cross-sections cannot. The price is attrition: dropouts are rarely random.' }));
bespoke['W9.14'] = () => repeat(3, () => { const levels = ['Systematic review / meta-analysis of RCTs', 'Randomised controlled trial', 'Cohort study', 'Case-control study', 'Case series / expert opinion']; const i = randInt(0, 3); const pair = shuffle([levels[i], levels[i + 1 + randInt(0, 3 - i)]]); return quizRound({ prompt: 'Stack the pyramid: which of these sits <b>higher</b> on the hierarchy of evidence (for questions about treatment effects)?', choices: pair, answer: pair.indexOf(levels[Math.min(...pair.map((p) => levels.indexOf(p)))]), why: `Order from top: ${levels.join(' › ')}. The hierarchy ranks designs by how well they rule out bias, not by sample size alone.` }); });
bespoke['W9.15'] = () => [multiPickRound({ prompt: 'Threat scanner: a study gives a new reading programme to volunteers from one school and compares their gains with a different school that did not volunteer. Flag every <b>threat to internal validity</b> present.', items: shuffle([
  { html: 'Selection: volunteers and non-volunteers differ to begin with', flaw: true, why: 'Groups were not equivalent at baseline.' },
  { html: 'History: events at one school but not the other could explain gains', flaw: true, why: 'Different settings experience different events.' },
  { html: 'Instrumentation: the same test was used at both times', flaw: false, why: '' },
  { html: 'Regression to the mean if volunteers were picked for low scores', flaw: true, why: 'Extreme baseline scores drift back by themselves.' },
  { html: 'The sample included both boys and girls', flaw: false, why: '' },
]) })];
bespoke['W9.16'] = () => repeat(2, () => quizRound({ prompt: 'Does it travel? A tightly controlled lab experiment on 60 psychology undergraduates shows a memory technique works. What is the main limit?', choices: ['External validity: it may not generalise to other people, settings or tasks', 'Internal validity: the effect is probably spurious', 'The sample is too small for any conclusion', 'The result is a Type I error'], answer: 0, why: 'Strong control buys internal validity. Whether the effect holds for older adults, in classrooms, with real material is a separate question of generalisation.' }));
bespoke['W9.17'] = () => repeat(2, () => quizRound({ prompt: 'Measure the right thing: a “customer loyalty” score is built only from how many emails a customer opens. What kind of validity is in doubt?', choices: ['Construct validity: email opens may not capture loyalty', 'Internal validity', 'Statistical conclusion validity', 'Test-retest reliability'], answer: 0, why: 'Construct validity asks whether the measurement really reflects the abstract concept. A reliable number can still measure the wrong thing.' }));
bespoke['W9.18'] = () => repeat(3, () => { const { xs, ys } = S.correlated(30, choice([0.5, 0.8, 0.95]), { mx: 70, sx: 10, my: 70, sy: 10 }); return corrRound({ prompt: 'Weigh it twice: 30 people took the same questionnaire two weeks apart. Guess the <b>test-retest reliability</b> (correlation of time 1 with time 2).', xs, ys, tolerance: 0.2 }); });
bespoke['W9.19'] = () => repeat(3, () => { const k = choice([4, 6, 10]), rb = choice([0.2, 0.3, 0.5]); const alpha = k * rb / (1 + (k - 1) * rb); return estimateRound({ prompt: `Item mixer: a scale has <b>${k}</b> items with average inter-item correlation <b>${rb}</b>. Estimate <b>Cronbach's α</b> = k·r̄ / (1 + (k − 1)·r̄).`, truth: alpha, tolerance: 0.12, min: 0, max: 1, step: 0.01, explain: `${k}×${rb} / (1 + ${k - 1}×${rb}) = ${fmt(alpha)}. More items, or more correlated items, raise α; 0.7–0.9 is the usual comfort zone, and very high α can mean redundant items.` }); });
bespoke['W9.20'] = () => repeat(3, () => { const a = randInt(20, 40), b = randInt(3, 12), c = randInt(3, 12), d = randInt(20, 40); const N = a + b + c + d; const po = (a + d) / N; const pe = ((a + b) * (a + c) + (c + d) * (b + d)) / (N * N); const kappa = (po - pe) / (1 - pe); return estimateRound({ prompt: `Two judges: two raters classified ${N} essays as pass/fail. Observed agreement is ${pct(po)}, but some agreement happens by chance (expected ${pct(pe)}). Estimate <b>Cohen's κ</b> = (pₒ − pₑ)/(1 − pₑ).`, view: `<table class="tbl"><tr><th></th><th>B: pass</th><th>B: fail</th></tr><tr><th>A: pass</th><td>${a}</td><td>${b}</td></tr><tr><th>A: fail</th><td>${c}</td><td>${d}</td></tr></table>`, truth: kappa, tolerance: 0.15, min: -0.2, max: 1, step: 0.01, explain: `κ = (${fmt(po, 2)} − ${fmt(pe, 2)}) / (1 − ${fmt(pe, 2)}) = ${fmt(kappa)}. Raw agreement flatters raters when one category dominates.` }); });
bespoke['W9.21'] = () => repeat(3, () => { const bias = choice([-3, -1.5, 1, 2, 4]); const d = normals(12, 100 + bias, 1.5); return estimateRound({ prompt: 'Calibrate: a certified 100 g weight was placed on the scale 12 times. Estimate the scale\'s <b>systematic error (bias)</b> = mean reading − 100.', data: d, truth: mean(d) - 100, tolerance: 1.2, min: -6, max: 6, step: 0.1, domain: [94, 106], explain: `Mean reading ${fmt(mean(d))}, so bias ≈ ${fmt(mean(d) - 100)}; the scatter (SD ${fmt(sd(d))}) is random error. Bias needs recalibration; random error needs averaging.` }); });
bespoke['W9.22'] = () => repeat(3, () => scenarioPick('Make it measurable: which is a sound operationalisation?', [
  { text: 'Concept: “student engagement”.', answer: 'Minutes of on-task behaviour coded from classroom video', why: 'Observable, repeatable, clearly tied to the concept.' },
  { text: 'Concept: “stress”.', answer: 'Salivary cortisol plus a validated 10-item stress questionnaire', why: 'Multiple measurable indicators of the construct.' },
  { text: 'Concept: “restaurant quality”.', answer: 'Mean rating from a standardised inspection checklist', why: 'A defined, repeatable procedure.' },
  { text: 'Concept: “happiness”.', answer: 'Self-reported life satisfaction on a validated 0–10 scale', why: 'A standard, validated measure.' },
], 4));
bespoke['W9.23'] = () => repeat(3, () => { const d = choice([0.2, 0.3, 0.5, 0.8]); const n = Math.ceil(2 * ((1.96 + 0.84) / d) ** 2); return estimateRound({ prompt: `Budget vs power: two-group trial, expected effect d = <b>${d}</b>, α = 0.05, desired power 80%. Roughly how many participants <b>per group</b>?`, truth: n, tolerance: 0.35 * n, min: 0, max: 800, step: 1, explain: `n ≈ 2 × ((1.96 + 0.84)/d)² = ${n} per group. Halving the effect size quadruples the sample. Budget the study to the effect you would care about, not the one you hope for.` }); });
bespoke['W9.24'] = () => [multiPickRound({ prompt: 'Lock the plan: the pre-registration said “primary outcome: depression score at 8 weeks; two-sided t-test; n = 120”. Flag every <b>deviation</b> in the published paper.', items: shuffle([
  { html: 'Reports anxiety at 4 weeks as the main result because depression was not significant', flaw: true, why: 'Outcome switching.' },
  { html: 'Uses a one-sided test “since we expected improvement”', flaw: true, why: 'Test changed after seeing the data.' },
  { html: 'Analyses all 120 randomised participants', flaw: false, why: '' },
  { html: 'Adds 40 participants after an interim look showed p = 0.08', flaw: true, why: 'Unplanned optional stopping / extension.' },
  { html: 'Reports the depression result at 8 weeks in the main table', flaw: false, why: '' },
]), submitText: 'File the audit' })];
bespoke['W9.25'] = () => [predictRound({ prompt: 'Hack the p: nothing is really going on, but you have <b>4 outcome measures</b>, <b>2 ways to define the groups</b>, and you may drop outliers or not (<b>2 choices</b>): 16 analyses. You report the best. P(at least one p < 0.05)?', truth: 1 - 0.95 ** 16, tolerance: 0.15, trial: () => (repeat(16, () => R() < 0.05).some(Boolean) ? 1 : 0), explain: `About ${pct(1 - 0.95 ** 16)} (treating the 16 as independent; correlated choices give a bit less). The garden of forking paths turns a 5% false-positive rate into a coin flip. Pre-registration prunes the garden.` })];
bespoke['W9.26'] = () => repeat(2, () => quizRound({ prompt: 'Sharpshooter: a study measured 30 variables, found that “left-handed participants slept more”, and the paper introduces this as its hypothesis from the outset. What is this?', choices: ['HARKing: hypothesising after the results are known', 'A legitimate exploratory finding, correctly reported', 'A Type II error', 'Blocking'], answer: 0, why: 'Presenting a post-hoc finding as a predicted one hides the multiple comparisons that produced it. Exploratory findings are fine if labelled as such and then tested on new data.' }));
bespoke['W9.27'] = () => [predictRound({ prompt: 'File drawer: 100 labs test a treatment that truly does <b>nothing</b>, at α = 0.05. Journals publish only “significant” results. How many of the 100 studies get published?', truth: 5, tolerance: 3, trial: () => (R() < 0.05 ? 1 : 0) * 100, min: 0, max: 30, step: 1, label: 'Published per 100 (running estimate)', explain: 'About 5, and every one of them is a false positive. Readers see 5 glowing papers and 0 of the 95 null results. Funnel plots and registered reports exist to expose this.' })];
bespoke['W9.28'] = () => repeat(2, () => quizRound({ prompt: 'Returning planes: bombers return with bullet holes mostly on the wings and tail, rarely on the engines. Where should you add armour?', choices: ['The engines: planes hit there did not come back to be counted', 'The wings and tail, where the holes are', 'Everywhere equally', 'Nowhere; the data show engines are rarely hit'], answer: 0, why: 'Survivorship bias: the sample contains only survivors. Holes on survivors mark the places a plane can be hit and still fly home.' }));
bespoke['W9.29'] = () => repeat(2, () => quizRound({ prompt: 'Through the door: a gym studies the health of its members and concludes gym membership causes good health. What is the main bias?', choices: ['Selection bias: healthier people are more likely to join a gym', 'Measurement error in health', 'Attrition', 'Hawthorne effect'], answer: 0, why: 'The process that puts people into the sample (joining) is related to the outcome. Selection into exposure confounds the comparison.' }));
bespoke['W9.30'] = () => repeat(3, () => { const n = 100; const drop = randInt(20, 40); const completers = randInt(60, 80); const itt = Math.round((completers * (n - drop) + 20 * drop) / n); return estimateRound({ prompt: `Who stayed: ${n} started a diet programme; <b>${drop}</b> dropped out (mostly those losing nothing). Completers show <b>${completers}%</b> success. If dropouts had about 20% success, what is the honest success rate counting <b>everyone who started</b>?`, truth: itt, tolerance: 6, min: 0, max: 100, step: 1, unit: '%', explain: `(${completers}% × ${n - drop} + 20% × ${drop}) / ${n} ≈ ${itt}%. Attrition that depends on the outcome inflates the completer-only result.` }); });
bespoke['W9.31'] = () => repeat(2, () => quizRound({ prompt: 'Watched: factory workers became more productive when the lights were brightened, and again when they were dimmed. Best explanation?', choices: ['Hawthorne effect: being observed changed behaviour, not the lighting', 'Lighting has a nonlinear effect on productivity', 'Regression to the mean', 'Measurement error'], answer: 0, why: 'Any change plus attention produced improvement. Control groups that get equal attention are the antidote.' }));
bespoke['W9.32'] = () => repeat(3, () => scenarioPick('Leading questions: what is the problem?', [
  { text: '“Most experts agree the policy helps families. Do you support it?”', answer: 'Leading wording pushes respondents toward yes', why: 'The preamble signals the desired answer.' },
  { text: 'The experimenter, who knows which group each participant is in, rates their improvement.', answer: 'Experimenter bias: unblinded assessment', why: 'Expectations shape ratings; blind the assessor.' },
  { text: 'Participants guess the study is about politeness and act extra polite.', answer: 'Demand characteristics', why: 'Participants perform the hypothesis they infer.' },
  { text: 'A computer scores the outcome automatically from the blinded data.', answer: 'No problem: objective, blinded measurement', why: 'This is the fix, not the flaw.' },
], 4));
bespoke['W9.33'] = () => repeat(2, () => quizRound({ prompt: 'Admission filter: in the general population, diabetes and gallstones are independent. A hospital admits anyone who has either condition. Among hospital patients, what will the data show, and why?', choices: ['A negative association: among admitted patients, not having one condition means you must have the other', 'A positive association: the conditions cluster', 'No association, as in the population', 'A positive association caused by shared risk factors'], answer: 0, why: 'Berkson’s paradox: conditioning on admission (a collider of the two conditions) manufactures a spurious negative association. Studies run inside hospitals or on volunteers can invent correlations this way.' }));
bespoke['W9.34'] = () => [(() => { const n = 20; const pw = S.powerTwoSample(0.5, n); return predictRound({ prompt: `Replication lab: a true effect of d = 0.5 exists. Each replication uses n = ${n} per group at α = 0.05. What fraction of replications “succeed” (p < 0.05)?`, truth: pw, tolerance: 0.15, trial: () => (S.welchT(normals(n, 55, 10), normals(n, 50, 10)).p < 0.05 ? 1 : 0), trials: 400, explain: `Only about ${pct(pw)}: that is the power. Low-powered replications “fail” even when the effect is real, and low-powered originals exaggerate the effects they find.` }); })()];
bespoke['W9.35'] = () => repeat(2, () => quizRound({ prompt: 'As randomised: in a trial, 30% of the treatment group stopped taking the drug. Which analysis preserves the benefit of randomisation?', choices: ['Intention-to-treat: analyse everyone in the group they were randomised to', 'Per-protocol: analyse only those who complied', 'Move non-compliers to the control group', 'Exclude non-compliers from both groups'], answer: 0, why: 'Compliers differ from non-compliers, so per-protocol analysis reintroduces selection bias. ITT estimates the effect of offering the treatment, as it would work in practice.' }));
bespoke['W9.36'] = () => repeat(3, () => scenarioPick('Found experiments: which is a credible natural experiment?', [
  { text: 'A lottery decides which families get housing vouchers; compare winners with losers.', answer: 'Credible: assignment was effectively random', why: 'The lottery is as good as a coin flip.' },
  { text: 'Compare towns that chose to adopt a policy with towns that did not.', answer: 'Not credible: towns self-selected', why: 'Adopters differ in other ways.' },
  { text: 'A minimum-wage rise applies in one state but not the neighbouring one; compare border counties before and after.', answer: 'Credible: a quasi-experiment with a comparison group (difference-in-differences)', why: 'Nearby counties give a plausible counterfactual trend.' },
], 3));
bespoke['W9.37'] = () => repeat(3, () => scenarioPick('Ethics gate: what is the issue?', [
  { text: 'Participants are told the study is about memory when it is about obedience, and are never debriefed.', answer: 'Deception without debriefing', why: 'Deception may be permitted only with justification and a full debrief.' },
  { text: 'A trial continues even though interim data show the drug is clearly harming patients.', answer: 'Failure to stop for harm (equipoise lost)', why: 'Data monitoring committees exist to stop such trials.' },
  { text: 'Survey responses are stored with names attached and shared with the participants’ employer.', answer: 'Breach of confidentiality', why: 'Data must be protected and used only as consented.' },
  { text: 'Participants sign a consent form after a clear explanation and can withdraw at any time.', answer: 'No issue: informed consent done properly', why: 'That is the standard.' },
], 4));

/* =========================== World 10: Frontier Fjords =========================== */
bespoke['W10.01'] = () => repeat(3, () => { const n = 10, k = randInt(2, 8); const p = choice([0.3, 0.5, 0.7]); const L = S.binomPmf(k, n, p); return estimateRound({ prompt: `Likelihood curve: you saw <b>${k}</b> heads in ${n} flips. The likelihood of p is L(p) = P(data | p). Estimate <b>L(${p})</b>.`, view: curvePlot([{ fn: (q) => S.binomPmf(k, n, Math.min(0.999, Math.max(0.001, q))) }], { domain: [0, 1], height: 170, lines: [{ v: p, cls: 'ref', label: `p = ${p}` }] }), truth: L, tolerance: 0.08, min: 0, max: 0.4, step: 0.005, explain: `L(${p}) = C(10,${k}) ${p}^${k} ${fmt(1 - p)}^${n - k} = ${fmt(L, 3)}. The likelihood is a function of the parameter with the data held fixed; it peaks at p = ${k / n}.` }); });
bespoke['W10.02'] = () => repeat(3, () => { const n = choice([12, 20, 25]), k = randInt(2, n - 2); return estimateRound({ prompt: `Hill climb: ${k} successes in ${n} trials. Which value of p makes these data most probable (the <b>maximum likelihood estimate</b>)?`, view: curvePlot([{ fn: (q) => S.binomPmf(k, n, Math.min(0.999, Math.max(0.001, q))) }], { domain: [0, 1], height: 170 }), truth: k / n, tolerance: 0.1, min: 0, max: 1, step: 0.01, explain: `The likelihood peaks at p̂ = k/n = ${fmt(k / n, 3)}. MLE picks the parameter under which what happened was most likely.` }); });
bespoke['W10.03'] = () => repeat(3, () => scenarioPick('State your belief: which prior fits?', [
  { text: 'You know nothing about a coin’s bias.', answer: 'Beta(1, 1): flat over 0–1', why: 'A uniform prior expresses no preference.' },
  { text: 'A coin from the mint: you are almost sure it is fair.', answer: 'Beta(100, 100): tightly concentrated at 0.5', why: 'A strong prior near 0.5.' },
  { text: 'A click-through rate you think is about 5% but are unsure.', answer: 'Beta(2, 38): centred near 0.05 and wide', why: 'Mean 2/40 = 0.05 with little weight (40 pseudo-observations).' },
  { text: 'You want the data to dominate quickly.', answer: 'A weak prior such as Beta(1, 1) or Beta(0.5, 0.5)', why: 'Few pseudo-observations get overwhelmed fast.' },
], 4));
bespoke['W10.04'] = () => repeat(3, () => { const a = choice([1, 2, 5]), b = choice([1, 2, 5]); const n = randInt(5, 20), k = randInt(0, n); const post = (a + k) / (a + b + n); return estimateRound({ prompt: `Update lab: prior Beta(<b>${a}</b>, <b>${b}</b>) for a success rate. You observe <b>${k}</b> successes in <b>${n}</b> trials. What is the <b>posterior mean</b>?`, truth: post, tolerance: 0.1, min: 0, max: 1, step: 0.01, explain: `Posterior is Beta(${a + k}, ${b + n - k}) with mean (${a}+${k})/(${a}+${b}+${n}) = ${fmt(post, 3)}: a weighted blend of the prior mean ${fmt(a / (a + b), 2)} and the data ${fmt(k / n, 2)}.` }); });
bespoke['W10.05'] = () => repeat(2, () => quizRound({ prompt: 'Belief band: a 95% <b>credible</b> interval for a mean is [4.1, 4.9]. Which statement is correct?', choices: ['Given the data and prior, there is a 95% probability the mean lies in [4.1, 4.9]', '95% of repeated samples would give intervals containing the mean', 'The mean is definitely between 4.1 and 4.9', 'The p-value is 0.05'], answer: 0, why: 'A credible interval is a direct probability statement about the parameter, which is what people usually (wrongly) think a confidence interval says.' }));
bespoke['W10.06'] = () => repeat(3, () => { const n = 20, k = randInt(8, 16); const bf = S.binomPmf(k, n, 0.5) / S.binomPmf(k, n, 0.7); return estimateRound({ prompt: `Evidence scale: ${k} heads in ${n} flips. H₁: p = 0.5 versus H₂: p = 0.7. Estimate the <b>Bayes factor</b> BF₁₂ = P(data | H₁) / P(data | H₂).`, truth: bf, tolerance: 0.4 * bf + 0.2, min: 0, max: Math.max(5, bf * 2), step: 0.05, explain: `${fmt(S.binomPmf(k, n, 0.5), 4)} / ${fmt(S.binomPmf(k, n, 0.7), 4)} = ${fmt(bf)}. ${bf > 1 ? 'The data favour p = 0.5' : 'The data favour p = 0.7'} by that factor; multiply your prior odds by it.` }); });
bespoke['W10.07'] = () => repeat(3, () => { const a = randInt(1, 5), b = randInt(1, 5), n = randInt(5, 15), k = randInt(0, n); const good = `Beta(${a + k}, ${b + n - k})`; const opts = shuffle([good, `Beta(${a + n}, ${b + k})`, `Beta(${k}, ${n - k})`, `Beta(${a * k + 1}, ${b * (n - k) + 1})`]); return quizRound({ prompt: `Add the counts: prior Beta(${a}, ${b}); data ${k} successes, ${n - k} failures. What is the posterior?`, choices: opts, answer: opts.indexOf(good), why: `Conjugacy: Beta(${a}, ${b}) + ${k} successes and ${n - k} failures → ${good}. The prior acts like ${a + b} pseudo-observations.` }); });
bespoke['W10.08'] = () => repeat(2, () => quizRound({ prompt: 'Random walker: an MCMC chain’s trace plot shows the first 500 samples drifting from the start value before settling into a stable band. What should you do?', choices: ['Discard the drifting burn-in, run multiple chains and check they mix (R̂ ≈ 1)', 'Use all samples; more is better', 'Stop the chain early to avoid bias', 'Restart from the mean'], answer: 0, why: 'MCMC samples the posterior only after convergence. Burn-in removal, multiple chains and diagnostics like R̂ and effective sample size are standard hygiene.' }));
bespoke['W10.09'] = () => [(() => { const a = skewed(10, 20, 0.5).map((v) => v + 6), b = skewed(10, 20, 0.5); const pooled = [...a, ...b]; const obs = median(a) - median(b); return samplerRound({ prompt: `Shuffle engine: observed difference in <b>medians</b> A − B = <b>${fmt(obs)}</b>. Each “sample” shuffles the labels and recomputes the median difference. No formula for the SE of a median difference is needed.`, population: pooled, sampleSize: 20, stat: () => { const sh = shuffle(pooled); return median(sh.slice(0, 10)) - median(sh.slice(10)); }, statName: 'shuffled median difference', popLabel: 'Pooled values', minDraws: 200, question: { prompt: 'What fraction of shuffles are at least as extreme (either direction)? That is the permutation p-value.', truth: (st) => st.filter((d) => Math.abs(d) >= Math.abs(obs)).length / st.length, tolerance: 0.12, min: 0, max: 1, explain: (st, t) => `p ≈ ${fmt(t, 3)}. Permutation tests work for any statistic you can compute.` } }); })()];
bespoke['W10.10'] = () => [predictRound({ prompt: 'Dart π: throw darts uniformly at the unit square. What fraction land inside the quarter circle x² + y² ≤ 1?', truth: Math.PI / 4, tolerance: 0.1, trial: () => (R() ** 2 + R() ** 2 <= 1 ? 1 : 0), trials: 4000, explain: `Area of the quarter circle = π/4 ≈ ${fmt(Math.PI / 4, 4)}. Multiply the running fraction by 4 to estimate π: Monte Carlo turns probability into computation.` })];
bespoke['W10.11'] = () => [(() => { const pr = 0.7, pd = 0.3; let state = 1; const steady = pd / (1 - pr + pd); return predictRound({ prompt: `Weather hopper: if today is rainy, tomorrow is rainy with probability <b>${pr}</b>; if dry, rainy with probability <b>${pd}</b>. In the long run, what fraction of days are rainy?`, truth: steady, tolerance: 0.1, trial: () => { state = R() < (state ? pr : pd) ? 1 : 0; return state; }, trials: 3000, explain: `Stationary distribution: π_rain = ${pd} / (1 − ${pr} + ${pd}) = ${fmt(steady, 3)}. A Markov chain forgets its start and settles to this balance.` }); })()];
bespoke['W10.12'] = () => repeat(3, () => { const slope = choice([0.5, 1, 2, -1]); const ys = Array.from({ length: 30 }, (_, t) => 50 + slope * t + S.randNormal(0, 4)); const f = S.linreg(ys.map((_, i) => i), ys); return estimateRound({ prompt: 'Draw the trend: estimate the <b>trend</b>, the average change per period.', view: lineChart([{ ys }], { height: 200, label: 'period' }), truth: f.slope, tolerance: 0.5, min: -3, max: 4, step: 0.05, explain: `Fitted slope ${fmt(f.slope)} per period (the generator used ${slope}). Trend is the slow drift; what is left is seasonality plus noise.` }); });
bespoke['W10.13'] = () => repeat(3, () => { const per = choice([4, 6, 12]); const ys = Array.from({ length: 48 }, (_, t) => 50 + 10 * Math.sin(2 * Math.PI * t / per) + S.randNormal(0, 2)); return quizRound({ prompt: `Find the period: this series repeats. What is its <b>seasonal period</b>?${lineChart([{ ys }], { height: 180, label: 'month' })}`, choices: ['4', '6', '12'], answer: ['4', '6', '12'].indexOf(String(per)), why: `The pattern repeats every ${per} periods. Seasonal adjustment subtracts that repeating component so the trend and anomalies are visible.` }); });
bespoke['W10.14'] = () => repeat(3, () => { const phi = choice([0.2, 0.6, 0.9, -0.6]); const x = [0]; for (let t = 1; t < 80; t++) x.push(phi * x[t - 1] + S.randNormal(0, 1)); return corrRound({ prompt: `Lag lens: each point plots x<sub>t</sub> (horizontal) against x<sub>t+1</sub> (vertical). Guess the <b>lag-1 autocorrelation</b>.${lineChart([{ ys: x }], { height: 120 })}`, xs: x.slice(0, -1), ys: x.slice(1), tolerance: 0.25 }); });
bespoke['W10.15'] = () => repeat(3, () => { const ys = Array.from({ length: 12 }, () => randInt(10, 40)); const i = randInt(1, 10); const ma = mean(ys.slice(i - 1, i + 2)); return estimateRound({ prompt: `Smooth operator: series ${ys.join(', ')}. What is the centred <b>3-point moving average</b> at position ${i + 1} (values ${ys[i - 1]}, ${ys[i]}, ${ys[i + 1]})?`, truth: ma, tolerance: 2, min: 0, max: 50, step: 0.1, explain: `(${ys[i - 1]} + ${ys[i]} + ${ys[i + 1]}) / 3 = ${fmt(ma)}. Wider windows smooth more but lag and blur turning points.` }); });
bespoke['W10.16'] = () => [(() => { const sim = () => { const a = [0], b = [0]; for (let t = 1; t < 60; t++) { a.push(a[t - 1] + S.randNormal()); b.push(b[t - 1] + S.randNormal()); } return Math.abs(S.pearson(a, b)); }; const truth = mean(repeat(400, () => (sim() > 0.5 ? 1 : 0))); return predictRound({ prompt: 'Fake friends: two <b>completely independent random walks</b> of 60 steps. P(|correlation| > 0.5 between them)?', truth, tolerance: 0.15, trial: () => (sim() > 0.5 ? 1 : 0), trials: 300, explain: `About ${pct(truth)}. Non-stationary series trend together by accident (spurious regression). Difference them first, or test for cointegration.` }); })()];
bespoke['W10.17'] = () => repeat(2, () => quizRound({ prompt: 'Fan chart: a forecast shows a central line with a band that widens further into the future. Why does the band widen?', choices: ['Uncertainty accumulates: each step adds unknown shocks', 'The model gets less accurate because it is older', 'Seasonality grows over time', 'It is a drawing convention with no meaning'], answer: 0, why: 'Forecast error variance grows with horizon because future shocks pile up. Honest forecasts show intervals, and the honest shape is a fan.' }));
bespoke['W10.18'] = () => repeat(2, () => quizRound({ prompt: 'Still going: in a 5-year survival study, a patient is alive and well when the study ends at year 5. How should their record be treated?', choices: ['Right-censored at 5 years: we know survival ≥ 5, not the exact time', 'Excluded: no event occurred', 'Recorded as a death at year 5', 'Recorded as surviving forever'], answer: 0, why: 'Censoring keeps the information “survived at least this long”. Dropping censored cases biases survival downward; treating them as events biases it further.' }));
bespoke['W10.19'] = () => repeat(3, () => { const rows = [[10, randInt(1, 2)], [0, randInt(1, 2)], [0, randInt(0, 2)]]; let n = 10, s = 1; const steps = rows.map(([_, d], i) => { const c = i === 1 ? 1 : 0; s *= 1 - d / n; const out = { t: i + 1, n, d, s }; n -= d + c; return out; }); const t = randInt(1, 3); return estimateRound({ prompt: `Step down (Kaplan–Meier): 10 patients. Events: ${steps.map((r) => `at t = ${r.t}, ${r.d} died of ${r.n} at risk`).join('; ')} (one patient censored after t = 2). Estimate <b>S(${t})</b>.`, truth: steps[t - 1].s, tolerance: 0.12, min: 0, max: 1, step: 0.01, explain: `S(t) = Π(1 − dᵢ/nᵢ): ${steps.slice(0, t).map((r) => `(1 − ${r.d}/${r.n})`).join(' × ')} = ${fmt(steps[t - 1].s, 3)}. Censoring reduces the number at risk without counting as an event.` }); });
bespoke['W10.20'] = () => repeat(2, () => quizRound({ prompt: 'Rate ratio: a Cox model gives hazard ratio 0.6 for treatment vs control. Which reading is right?', choices: ['At any moment, treated patients’ instantaneous risk of the event is 60% of controls’', 'Treated patients live 40% longer', '60% of treated patients survive', 'The treatment delays the event by 0.6 years'], answer: 0, why: 'The hazard ratio compares instantaneous event rates, assumed constant over time (proportional hazards). It is not a difference in survival time or probability.' }));
bespoke['W10.21'] = () => repeat(3, () => { const st = repeat(3, () => ({ est: +(0.2 + R() * 0.6).toFixed(2), se: choice([0.05, 0.1, 0.2, 0.3]) })); const w = st.map((s) => 1 / s.se ** 2); const pooled = S.sum(st.map((s, i) => s.est * w[i])) / S.sum(w); return estimateRound({ prompt: `Pool the studies: three trials report effects ${st.map((s) => `${s.est} (SE ${s.se})`).join(', ')}. Estimate the <b>fixed-effect pooled estimate</b> (weights 1/SE²).`, truth: pooled, tolerance: 0.08, min: 0, max: 1, step: 0.01, explain: `Weights ${w.map((x) => fmt(x, 0)).join(', ')}: pooled = ${fmt(pooled, 3)}. The precise study dominates; the plain average would be ${fmt(mean(st.map((s) => s.est)), 3)}.` }); });
bespoke['W10.22'] = () => repeat(2, () => quizRound({ prompt: 'Read the forest: in a forest plot, one study’s square is tiny with a very wide horizontal line crossing 1; the diamond at the bottom sits left of 1 and does not touch it. What does this say?', choices: ['That study is imprecise and inconclusive alone; the pooled estimate shows a significant benefit', 'That study is the most important', 'The pooled result is not significant', 'The studies disagree'], answer: 0, why: 'Square size = weight, line = CI, diamond = pooled estimate and its CI. A diamond clear of the null line is a significant pooled effect.' }));
bespoke['W10.23'] = () => repeat(3, () => { const k = choice([5, 8, 12]); const Q = +(k - 1 + R() * 3 * (k - 1)).toFixed(1); const i2 = Math.max(0, (Q - (k - 1)) / Q); return estimateRound({ prompt: `Same effect? ${k} studies, Cochran's Q = <b>${Q}</b> on ${k - 1} df. Estimate <b>I²</b> = (Q − df)/Q, the share of variation due to real differences between studies.`, truth: i2, tolerance: 0.12, min: 0, max: 1, step: 0.01, explain: `(${Q} − ${k - 1}) / ${Q} = ${pct(i2)}. Rough bands: 25% low, 50% moderate, 75% high heterogeneity; high I² calls for random effects and a look at subgroups.` }); });
bespoke['W10.24'] = () => repeat(2, () => quizRound({ prompt: 'Missing corner: a funnel plot (effect size vs precision) has small imprecise studies only on the right (favourable) side; the bottom-left is empty. What does this suggest?', choices: ['Publication bias: small unfavourable studies were never published', 'Small studies are more accurate', 'The treatment works better in small samples', 'Nothing; funnels are always asymmetric'], answer: 0, why: 'Without bias, small studies scatter symmetrically around the pooled effect. A missing corner is the file drawer made visible; trim-and-fill estimates what is missing.' }));
bespoke['W10.25'] = () => repeat(2, () => quizRound({ prompt: 'Weight shift: switching from fixed-effect to random-effects meta-analysis, what happens to the weights and the interval?', choices: ['Weights become more equal (small studies gain) and the CI widens', 'Large studies gain weight and the CI narrows', 'Nothing changes unless I² = 0', 'The pooled estimate always moves toward zero'], answer: 0, why: 'Random effects add between-study variance τ² to every study’s variance, which flattens the weights and widens the interval to reflect that true effects vary.' }));
bespoke['W10.26'] = () => repeat(3, () => { const grand = 70, gm = randInt(50, 90), n = choice([3, 10, 40]); const B = choice([0.3, 0.6, 0.9]); const shrunk = grand + (1 - B / (1 + (n - 1) * 0.1 * B)) * (gm - grand); const w = n / (n + 5); const est = grand + w * (gm - grand); return estimateRound({ prompt: `Pull toward the middle: the overall mean across schools is <b>${grand}</b>. One school with n = <b>${n}</b> pupils has mean <b>${gm}</b>. A hierarchical model weights the school's own mean by n/(n + 5). What is its <b>shrunken estimate</b>?`, truth: est, tolerance: 4, min: 40, max: 100, step: 0.5, explain: `${grand} + ${fmt(w, 2)} × (${gm} − ${grand}) = ${fmt(est)}. Small groups borrow strength from the pool; large groups keep their own mean. This is partial pooling.` }); });
bespoke['W10.27'] = () => repeat(3, () => { const vb = choice([4, 10, 25]), vw = choice([5, 15, 30]); return estimateRound({ prompt: `Family resemblance: between-cluster variance <b>${vb}</b>, within-cluster variance <b>${vw}</b>. Estimate the <b>intraclass correlation</b> (share of variance that is between clusters).`, truth: vb / (vb + vw), tolerance: 0.1, min: 0, max: 1, step: 0.01, explain: `ICC = ${vb}/(${vb} + ${vw}) = ${fmt(vb / (vb + vw), 3)}. Even a small ICC inflates the effective sample size problem in clustered data (design effect = 1 + (m − 1)·ICC).` }); });
bespoke['W10.28'] = () => repeat(2, () => quizRound({ prompt: 'Both worlds: for one patient, the potential outcome with treatment is Y(1) and without is Y(0). What is the fundamental problem of causal inference?', choices: ['We can observe only one of Y(1) and Y(0) for each unit', 'Y(0) is always zero', 'Treatments cannot be randomised', 'Outcomes are measured with error'], answer: 0, why: 'The individual causal effect Y(1) − Y(0) is never observed. Randomisation lets us estimate the average effect by comparing groups that are exchangeable.' }));
bespoke['W10.29'] = () => repeat(3, () => scenarioPick('Draw the arrows: in the DAG, what role does the variable play?', [
  { text: 'Z → X and Z → Y (Z causes both treatment and outcome).', answer: 'Confounder: adjust for it', why: 'A common cause opens a backdoor path.' },
  { text: 'X → M → Y (M lies on the causal path from X to Y).', answer: 'Mediator: do not adjust if you want the total effect', why: 'Adjusting blocks part of the effect you are measuring.' },
  { text: 'X → C ← Y (both X and Y cause C).', answer: 'Collider: adjusting for it creates bias', why: 'Conditioning on a common effect induces a spurious association.' },
  { text: 'Z → X only, and Z affects Y only through X.', answer: 'Instrument: can identify the effect even with unmeasured confounding', why: 'An instrument nudges X without touching Y directly.' },
], 4));
bespoke['W10.30'] = () => repeat(2, () => quizRound({ prompt: 'Block the backdoors: DAG: Z → X, Z → Y, X → C, Y → C, X → Y. To estimate the effect of X on Y, what is the minimal adjustment set?', choices: ['{Z}', '{Z, C}', '{C}', '{} (nothing)'], answer: 0, why: 'Z opens the backdoor X ← Z → Y, so adjust for Z. C is a collider (X → C ← Y): adjusting for it opens a new biasing path. More control is not always better.' }));
bespoke['W10.31'] = () => repeat(2, () => quizRound({ prompt: 'Nudge, not cause: to estimate the effect of schooling on wages, a researcher uses distance to the nearest college as an instrument. Which assumption is doing the heavy lifting?', choices: ['Distance affects wages only through schooling (exclusion restriction)', 'Distance is correlated with schooling', 'Wages are normally distributed', 'Distance is measured without error'], answer: 0, why: 'Relevance (distance predicts schooling) can be checked; the exclusion restriction (no other path to wages) cannot be tested and must be argued.' }));
bespoke['W10.32'] = () => repeat(3, () => { const tb = randInt(40, 60), ta = tb + randInt(5, 20), cb = randInt(40, 60), ca = cb + randInt(0, 10); const did = (ta - tb) - (ca - cb); return estimateRound({ prompt: `Two lines: treated city: <b>${tb}</b> before, <b>${ta}</b> after. Comparison city: <b>${cb}</b> before, <b>${ca}</b> after. Estimate the <b>difference-in-differences</b> effect.`, view: scatter([0, 1, 0, 1], [tb, ta, cb, ca], { height: 180, domain: [-0.3, 1.3], range: [30, 90], lines: [{ slope: ta - tb, intercept: tb, cls: 'guess' }, { slope: ca - cb, intercept: cb, cls: '' }], xLabel: 'before (0) → after (1). Orange: treated. Green: comparison.' }), truth: did, tolerance: 4, min: -10, max: 30, step: 0.5, explain: `(${ta} − ${tb}) − (${ca} − ${cb}) = ${did}. The comparison city supplies the trend that would have happened anyway (the parallel-trends assumption).` }); });
bespoke['W10.33'] = () => repeat(2, () => quizRound({ prompt: 'Make them match: what does a propensity score summarise, and what does matching on it achieve?', choices: ['P(treatment | covariates); matching balances the measured covariates between groups', 'P(outcome | treatment); matching equalises outcomes', 'The effect size; matching removes it', 'The sample weight; matching fixes non-response'], answer: 0, why: 'Units with equal propensity scores have the same covariate distribution on average, mimicking randomisation on observed variables. Unmeasured confounders remain.' }));
bespoke['W10.34'] = () => repeat(3, () => { const jump = choice([5, 10, 15, -8]); const xs = uniforms(60, 0, 100); const ys = xs.map((x) => 30 + 0.3 * x + (x >= 50 ? jump : 0) + S.randNormal(0, 3)); return estimateRound({ prompt: 'Jump at the line: a scholarship is given to everyone scoring ≥ 50. Estimate the <b>jump</b> in the outcome at the cutoff (the regression-discontinuity effect).', view: scatter(xs, ys, { height: 220, lines: [], xLabel: 'score (cutoff at 50)' }), truth: jump, tolerance: 4, min: -15, max: 25, step: 0.5, explain: `The outcome jumps by about ${jump} at 50; the smooth trend on both sides is what would have continued. People just above and below the cutoff are near-identical, so the jump is causal.` }); });
bespoke['W10.35'] = () => repeat(4, () => classify('Why is it missing?', [
  { text: 'A lab machine randomly fails on 5% of samples regardless of their values.', answer: 'MCAR', why: 'Missingness unrelated to anything: missing completely at random.' },
  { text: 'Older respondents skip the income question more often; age is recorded.', answer: 'MAR', why: 'Missingness depends on an observed variable (age): missing at random.' },
  { text: 'People with very high incomes refuse to report their income.', answer: 'MNAR', why: 'Missingness depends on the missing value itself: missing not at random.' },
  { text: 'A page of the survey was lost in the post for a random subset.', answer: 'MCAR', why: 'Random loss.' },
  { text: 'Sicker patients miss follow-up visits, and sickness was measured at baseline.', answer: 'MAR', why: 'Depends on observed baseline sickness.' },
], ['MCAR', 'MAR', 'MNAR']));
bespoke['W10.36'] = () => repeat(2, () => quizRound({ prompt: 'Fill the gaps: you replace every missing income with the mean income. What goes wrong?', choices: ['Variance and correlations are understated; standard errors become too small', 'Nothing; the mean is unbiased', 'The sample size falls', 'Bias is introduced in the mean'], answer: 0, why: 'Mean imputation squashes the distribution and pretends the filled values were observed. Multiple imputation draws plausible values several times and propagates the uncertainty.' }));
bespoke['W10.37'] = () => repeat(2, () => { const { xs, ys } = S.correlated(60, 0.9); return quizRound({ prompt: `Find the axis: which direction is the <b>first principal component</b> of this cloud?${scatter(xs, ys, { height: 220 })}`, choices: ['Along the long diagonal of the cloud (where variance is largest)', 'Along the x-axis', 'Along the y-axis', 'Perpendicular to the long diagonal'], answer: 0, why: 'PC1 is the direction of maximum variance; PC2 is perpendicular. Projecting onto PC1 keeps most of the information in one number.' }); });
bespoke['W10.38'] = () => repeat(2, () => quizRound({ prompt: 'Hidden factors: 12 questionnaire items; items 1–6 correlate strongly with each other, items 7–12 with each other, and the two blocks barely at all. What does factor analysis suggest?', choices: ['Two latent factors, one per block', 'One factor', 'Twelve factors', 'No structure'], answer: 0, why: 'Blocks of inter-correlated items point to a shared latent variable each. Factor loadings tell you which items measure which factor.' }));
bespoke['W10.39'] = () => repeat(3, () => { const k = choice([2, 3, 4]); const centres = [[20, 20], [70, 30], [40, 75], [80, 80]].slice(0, k); const xs = [], ys = []; for (const [cx, cy] of centres) for (let i = 0; i < 25; i++) { xs.push(cx + S.randNormal(0, 5)); ys.push(cy + S.randNormal(0, 5)); } return quizRound({ prompt: `Centre chaser: how many clusters (k) would k-means sensibly find here?${scatter(xs, ys, { height: 230, domain: [0, 100], range: [0, 100] })}`, choices: ['2', '3', '4', '5'], answer: k - 2, why: `${k} well-separated blobs. k-means alternates assigning points to the nearest centre and moving centres to their points’ mean; the elbow or silhouette plot helps choose k when it is not obvious.` }); });
bespoke['W10.40'] = () => repeat(2, () => quizRound({ prompt: 'Merge tree: in hierarchical (agglomerative) clustering, what does cutting the dendrogram at a given height do?', choices: ['Chooses the number of clusters: every branch below the cut is one cluster', 'Removes outliers', 'Standardises the variables', 'Fixes the random seed'], answer: 0, why: 'The tree records every merge; the height is the distance at which clusters joined. Cutting lower gives more, tighter clusters.' }));
bespoke['W10.41'] = () => repeat(3, () => { const n = choice([2000, 5000, 10000]); const pa = 0.05, pb = pa + choice([0, 0.005, 0.01]); const ka = Math.round(n * pa + S.randNormal(0, Math.sqrt(n * pa * (1 - pa)))), kb = Math.round(n * pb + S.randNormal(0, Math.sqrt(n * pb * (1 - pb)))); const p1 = ka / n, p2 = kb / n, pp = (ka + kb) / (2 * n); const z = (p2 - p1) / Math.sqrt(pp * (1 - pp) * 2 / n); const p = 2 * (1 - S.normalCdf(Math.abs(z))); return sigBetRound({ prompt: `Ship or skip: checkout A converted <b>${ka}</b> of ${n.toLocaleString()} (${fmt(p1 * 100, 2)}%); checkout B converted <b>${kb}</b> of ${n.toLocaleString()} (${fmt(p2 * 100, 2)}%). Two-proportion z-test.`, view: barChart([{ label: 'A', value: +(p1 * 100).toFixed(2) }, { label: 'B', value: +(p2 * 100).toFixed(2) }], { height: 150, yLabel: '% converting' }), result: { p, text: `z = ${fmt(z)}. ${pb > pa ? `B was truly better by ${fmt((pb - pa) * 100, 1)} points.` : 'A and B were truly identical.'} Significance is not the same as a lift worth the engineering cost.` } }); });
bespoke['W10.42'] = () => [(() => { const looks = 10, chunk = 20; const trial = () => { let a = [], b = []; for (let l = 0; l < looks; l++) { a = a.concat(normals(chunk, 50, 10)); b = b.concat(normals(chunk, 50, 10)); if (S.welchT(a, b).p < 0.05) return 1; } return 0; }; const truth = mean(repeat(150, trial)); return predictRound({ prompt: `Don't peek: A and B are identical. You check the test after every ${chunk} users per arm, ${looks} times, and stop as soon as p < 0.05. What is the real false-positive rate?`, truth, tolerance: 0.12, trial, trials: 200, explain: `About ${pct(truth)}, not 5%. Each look is another chance to be fooled. Sequential designs fix this with alpha-spending boundaries or Bayesian decision rules.` }); })()];
bespoke['W10.43'] = () => repeat(2, () => quizRound({ prompt: 'Slot explorer: two ad variants; a multi-armed bandit (Thompson sampling) is used instead of a fixed 50/50 A/B test. What is the trade-off?', choices: ['Less traffic wasted on the worse arm, but less precise estimates and trickier inference', 'More precise estimates for both arms', 'No difference', 'It guarantees finding the best arm'], answer: 0, why: 'Bandits shift traffic toward arms that look better (exploitation) while still sampling others (exploration). Good when the cost of the worse arm matters more than a clean estimate.' }));
bespoke['W10.44'] = () => repeat(4, () => classify('Pick the link: which GLM family and link suit this outcome?', [
  { text: 'Whether a customer churns (yes/no).', answer: 'Binomial with logit link (logistic regression)', why: 'Binary outcome.' },
  { text: 'Number of ER visits per patient per year.', answer: 'Poisson (or negative binomial) with log link', why: 'Counts, non-negative.' },
  { text: 'Blood pressure in mmHg.', answer: 'Normal with identity link (ordinary regression)', why: 'Continuous, roughly symmetric.' },
  { text: 'Insurance claim amounts, positive and right-skewed.', answer: 'Gamma with log link', why: 'Positive, skewed continuous outcome.' },
], ['Binomial with logit link (logistic regression)', 'Poisson (or negative binomial) with log link', 'Normal with identity link (ordinary regression)', 'Gamma with log link']));
bespoke['W10.45'] = () => repeat(2, () => quizRound({ prompt: 'Bump stacker: a kernel density estimate places a little bump on every data point and adds them up. What does a very small bandwidth do?', choices: ['Produces a spiky curve that follows noise (undersmoothing)', 'Produces an over-smooth single hump', 'Changes the area under the curve', 'Makes the estimate unbiased'], answer: 0, why: 'Bandwidth is the bump width: too small chases noise, too large hides structure. Like histogram bin width, but without the arbitrary bin edges.' }));
bespoke['W10.46'] = () => repeat(4, () => classify('Two lenses: which school of thought does this statement belong to?', [
  { text: '“The probability that the parameter lies in this interval is 95%.”', answer: 'Bayesian', why: 'Parameters have probability distributions.' },
  { text: '“In repeated sampling, 95% of such intervals would contain the fixed true value.”', answer: 'Frequentist', why: 'Probability is long-run frequency; the parameter is fixed.' },
  { text: '“We update our prior beliefs with the likelihood to obtain the posterior.”', answer: 'Bayesian', why: 'Prior → posterior updating.' },
  { text: '“The p-value is the probability of data this extreme if the null were true.”', answer: 'Frequentist', why: 'Probability of data given a hypothesis.' },
  { text: '“Given the data, the hypothesis has a 20% probability.”', answer: 'Bayesian', why: 'Probability assigned to a hypothesis.' },
], ['Bayesian', 'Frequentist']));

/* =========================== World 11: Reporting Reef =========================== */
bespoke['W11.01'] = () => repeat(2, () => quizRound({ prompt: 'Find the primary: an abstract reports “a significant improvement in secondary outcome B (p = 0.03)” and mentions in passing that the primary outcome A “showed a positive trend (p = 0.21)”. What is the honest summary?', choices: ['The trial did not show an effect on its primary outcome; the secondary result is exploratory', 'The treatment works, as outcome B shows', 'Both outcomes improved', 'The trial was underpowered, so B counts instead'], answer: 0, why: 'The primary outcome is the pre-specified test of the hypothesis. Secondary and post-hoc results are hypothesis-generating, especially after a primary miss.' }));
bespoke['W11.02'] = () => repeat(3, () => { const n = randInt(20, 60); const a = normals(n, 52, 10), b = normals(n, 48, 10); const r = S.welchT(a, b); const d = S.cohensD(a, b); const good = `t(${fmt(r.df, 1)}) = ${fmt(r.t)}, ${S.fmtP(r.p)}, d = ${fmt(d)}`; const opts = shuffle([good, `t = ${fmt(r.t)}, p = ${r.p < 0.05 ? '0.000' : fmt(r.p, 1)}`, `${S.fmtP(r.p)} (significant)`, `t(${n}) = ${fmt(r.t)}, p > 0.05, d = ${fmt(d * 10)}`]); return quizRound({ prompt: `Fill the sentence: group A (M = ${fmt(mean(a))}, SD = ${fmt(sd(a))}) vs group B (M = ${fmt(mean(b))}, SD = ${fmt(sd(b))}), n = ${n} each. Which is the complete, correctly formatted report of the t-test?`, choices: opts, answer: opts.indexOf(good), why: 'Report the statistic with its degrees of freedom, an exact p-value (p < .001 only below that), and an effect size. Never “p = 0.000”.' }); });
bespoke['W11.03'] = () => repeat(3, () => { const t = [[randInt(20, 40), randInt(10, 30)], [randInt(10, 30), randInt(20, 40)]]; const r = S.chiSquare(t); const N = S.sum(t.flat()); const good = `χ²(1, N = ${N}) = ${fmt(r.stat)}, ${S.fmtP(r.p)}`; const opts = shuffle([good, `χ² = ${fmt(r.stat)}, significant`, `χ²(${N}) = ${fmt(r.stat)}, p = ${fmt(r.p, 1)}`, `t(1) = ${fmt(r.stat)}, ${S.fmtP(r.p)}`]); return quizRound({ prompt: `Fill the sentence II: a 2×2 chi-square test on N = ${N}. Which report is correct?`, choices: opts, answer: opts.indexOf(good), why: 'Chi-square reports degrees of freedom and N, the statistic, and the exact p. The df for a 2×2 table is (2−1)(2−1) = 1.' }); });
bespoke['W11.04'] = () => repeat(2, () => quizRound({ prompt: 'Table reader: a regression table shows: <code>hours_studied  β = 2.1  SE = 0.4  p < .001</code> and <code>coffee_cups  β = 0.3  SE = 0.9  p = .74</code>. What is a correct reading?', choices: ['Each extra hour studied predicts 2.1 more marks, holding coffee constant; coffee’s effect is indistinguishable from zero', 'Coffee has no effect in reality', 'Studying causes 2.1 marks per hour', 'Coffee matters more because its β is positive'], answer: 0, why: 'β is the adjusted slope; SE and p tell you its precision. “Not significant” means “not distinguishable from zero here”, not “zero”. Causal language needs a design that supports it.' }));
bespoke['W11.05'] = () => repeat(2, () => quizRound({ prompt: 'Star gazer: a table marks results with *, **, ***. Which claim is unjustified?', choices: ['A *** result is a bigger or more important effect than a * result', '*** usually means p < 0.001', 'Stars convey significance thresholds only', 'A result with no star may still be practically important'], answer: 0, why: 'Stars rank p-values, which blend effect size with sample size. A tiny effect in a huge sample earns ***; a large effect in a small one earns none.' }));
bespoke['W11.06'] = () => repeat(4, () => { const lo = +(S.randNormal(0.5, 1)).toFixed(2), hi = +(lo + 0.3 + R() * 2).toFixed(2); const kind = lo > 0 ? 'Significant and positive; plausible values are all above zero' : hi < 0 ? 'Significant and negative; plausible values are all below zero' : 'Not significant; the data are compatible with no effect and with effects in either direction'; const opts = ['Significant and positive; plausible values are all above zero', 'Significant and negative; plausible values are all below zero', 'Not significant; the data are compatible with no effect and with effects in either direction']; return quizRound({ prompt: `Interval interpreter: 95% CI for a mean difference: <b>[${lo}, ${hi}]</b>. Reading?`, choices: opts, answer: opts.indexOf(kind), why: `${kind}. The interval width (${fmt(hi - lo)}) tells you the precision, which a bare p-value hides.` }); });
bespoke['W11.07'] = () => repeat(2, () => quizRound({ prompt: 'Subgroup sceptic: the overall trial effect is null (p = 0.6). Among 12 subgroups, “patients born under Libra” show benefit (p = 0.02). What should a careful reader conclude?', choices: ['Likely a chance finding from multiple subgroups; needs a pre-specified replication', 'The drug works for Libras', 'The overall result is wrong', 'The subgroup is too small to matter either way'], answer: 0, why: 'With 12 subgroups, one p < 0.05 is expected by chance. A famous cardiology trial really did report a star-sign subgroup to make this point.' }));
bespoke['W11.08'] = () => repeat(3, () => { const d = choice([0.2, 0.5, 0.8, 1.2]); const truth = S.normalCdf(d / Math.SQRT2); return estimateRound({ prompt: `Picture the effect: Cohen's d = <b>${d}</b>. If you pick one random treated person and one random control, what is the probability the treated one scores higher (the “common-language effect size”)?`, truth, tolerance: 0.08, min: 0.5, max: 1, step: 0.01, explain: `Φ(d/√2) = ${fmt(truth, 2)}. Even a “large” d = 0.8 only gives 71%: the groups overlap a lot. Picture distributions, not just a number.` }); });
bespoke['W11.09'] = () => repeat(3, () => { const a = randInt(80, 90), b = a + randInt(1, 4); const trunc = barChart([{ label: 'Brand X', value: a }, { label: 'Brand Y', value: b }].map((d) => ({ ...d, value: d.value - (a - 2) })), { height: 150, yLabel: `axis starts at ${a - 2}` }); const honest = barChart([{ label: 'Brand X', value: a }, { label: 'Brand Y', value: b }], { height: 150, yLabel: 'axis starts at 0' }); const opts = shuffle([{ html: honest, correct: true, why: `The real values are ${a}% and ${b}%: a ${b - a}-point gap. Starting the axis at ${a - 2} makes Y look several times bigger. Bar lengths must be proportional to values, so bars start at zero.` }, { html: trunc, correct: false }]); return pickRound({ prompt: `Reset the axis: both charts show satisfaction of ${a}% vs ${b}%. Which is the <b>honest</b> chart?`, options: opts }); });
bespoke['W11.10'] = () => repeat(2, () => quizRound({ prompt: 'Widen the window: a chart titled “Crime soars!” shows 2019–2021, a rise from a 30-year low. The full 1990–2021 series shows a long decline. What is the problem?', choices: ['Cherry-picked range: the start point was chosen to manufacture a trend', 'The y-axis is logarithmic', 'The data are seasonally adjusted', 'Nothing; recent data matter most'], answer: 0, why: 'Any noisy series rises from its minimum. Show the full context or justify the window in advance.' }));
bespoke['W11.11'] = () => repeat(2, () => quizRound({ prompt: 'Make them match: a chart plots ice-cream sales (left axis, 0–500) and shark attacks (right axis, 0–12) and the lines overlap perfectly. What can you conclude?', choices: ['Nothing: two independent axes can be scaled to make any two series overlap', 'Ice cream causes shark attacks', 'The correlation is about 1', 'Shark attacks cause ice-cream sales'], answer: 0, why: 'Dual axes have two free scales, so the visual “fit” is an artefact of scaling. Use indexed series or two panels instead.' }));
bespoke['W11.12'] = () => repeat(3, () => { const base = choice([1, 2, 4]), rr = choice([1.5, 2]); const treated = base * rr; const opts = shuffle([`Risk rises from ${base} in 1,000 to ${treated} in 1,000 (${pct(rr - 1)} relative increase)`, `Risk rises ${pct(rr - 1)}!`, `${pct(rr - 1)} of users will be harmed`, `Risk doubles for everyone`]); return quizRound({ prompt: `Honest headline: a study finds relative risk <b>${rr}</b> for a rare side effect with baseline risk <b>${base} in 1,000</b>. Pick the honest headline.`, choices: opts, answer: opts.indexOf(`Risk rises from ${base} in 1,000 to ${treated} in 1,000 (${pct(rr - 1)} relative increase)`), why: 'Give absolute risks in natural frequencies alongside any relative change. “Risk rises 100%” from 1 to 2 in 1,000 is an extra 1 in 1,000.' }); });
bespoke['W11.13'] = () => repeat(2, () => quizRound({ prompt: 'Linear or log: a chart of daily COVID cases shows a straight rising line on a log-scale y-axis. What does the straight line mean?', choices: ['Cases are growing by a constant percentage each day (exponential growth)', 'Cases are growing by a constant number each day', 'Growth has stopped', 'The data were transformed to hide the rise'], answer: 0, why: 'On a log scale, equal vertical steps are equal ratios. A straight line means constant multiplicative growth; a flattening means the growth rate is falling.' }));
bespoke['W11.14'] = () => repeat(3, () => { const n = choice([25, 100]), s = 10; const se = s / Math.sqrt(n); const ci = 1.96 * se; const kind = choice(['SD', 'SE', '95% CI']); const half = { SD: s, SE: se, '95% CI': ci }[kind]; return quizRound({ prompt: `What are the bars? A bar chart shows mean 50 with error bars of ±<b>${fmt(half)}</b>. The sample has n = ${n}, SD = ${s}. What do the bars represent?`, choices: ['SD', 'SE', '95% CI'], answer: ['SD', 'SE', '95% CI'].indexOf(kind), why: `SD = ${s}; SE = ${s}/√${n} = ${fmt(se)}; 95% CI ≈ 1.96 × SE = ${fmt(ci)}. Captions must say which, because SD bars describe the data while SE/CI bars describe the precision of the mean.` }); });
bespoke['W11.15'] = () => repeat(3, () => { const ratio = choice([1.5, 2, 3]); return estimateRound({ prompt: `Lie factor: sales grew ${ratio}×, so the designer drew the new money-bag icon ${ratio}× taller <b>and</b> ${ratio}× wider. By what factor does the icon's <b>area</b> grow?`, truth: ratio * ratio, tolerance: 1, min: 1, max: 10, step: 0.1, explain: `Area scales with both dimensions: ${ratio}² = ${ratio * ratio}. The eye reads area, so the chart exaggerates by a lie factor of ${ratio}. Pie slices and 3D bars distort the same way.` }); });
bespoke['W11.16'] = () => repeat(3, () => { const a = randInt(5, 30), b = a + randInt(2, 10); const q = choice(['points', 'percent']); return q === 'points' ? estimateRound({ prompt: `Points or percent: support rose from <b>${a}%</b> to <b>${b}%</b>. By how many <b>percentage points</b>?`, truth: b - a, tolerance: 2, min: 0, max: 20, step: 1, unit: ' pts', explain: `${b} − ${a} = ${b - a} percentage points; as a relative change it is ${pct((b - a) / a)}. Say which one you mean.` }) : estimateRound({ prompt: `Points or percent: support rose from <b>${a}%</b> to <b>${b}%</b>. What is the <b>relative (percent) change</b>?`, truth: (b - a) / a * 100, tolerance: 8, min: 0, max: 200, step: 1, unit: '%', explain: `(${b} − ${a}) / ${a} = ${pct((b - a) / a)} relative change, versus ${b - a} percentage points absolute.` }); });
bespoke['W11.17'] = () => [multiPickRound({ prompt: 'Checklist audit: flag every item a CONSORT-style trial report <b>must</b> include but this manuscript omits: “We randomised patients to drug or placebo and found the drug reduced pain (p = 0.04).”', items: shuffle([
  { html: 'How the random allocation sequence was generated and concealed', flaw: true, why: 'Required to judge selection bias.' },
  { html: 'Who was blinded', flaw: true, why: 'Required to judge performance and detection bias.' },
  { html: 'The number of participants randomised, lost and analysed in each arm (flow diagram)', flaw: true, why: 'Attrition changes everything.' },
  { html: 'The authors’ favourite colour', flaw: false, why: '' },
  { html: 'The effect size with a confidence interval, not just p', flaw: true, why: 'Readers need magnitude and precision.' },
  { html: 'A pre-registration or protocol reference', flaw: true, why: 'Shows the primary outcome was fixed in advance.' },
]), submitText: 'Return to authors' })];
bespoke['W11.18'] = () => repeat(4, () => classify('Verb detector: does this headline claim causation or just association?', [
  { text: '“Coffee linked to longer life”', answer: 'Association', why: '“Linked to” is correlational language.' },
  { text: '“Coffee extends life, study finds”', answer: 'Causal claim', why: '“Extends” asserts cause.' },
  { text: '“Screen time associated with poor sleep in teens”', answer: 'Association', why: '“Associated with” is correlational.' },
  { text: '“Screen time is ruining teens’ sleep”', answer: 'Causal claim', why: '“Ruining” asserts cause.' },
  { text: '“Exercise cuts dementia risk by a third”', answer: 'Causal claim', why: '“Cuts” is causal; check whether the design was randomised.' },
  { text: '“People who exercise have lower dementia rates”', answer: 'Association', why: 'Describes a difference between groups, not a cause.' },
], ['Association', 'Causal claim']));
bespoke['W11.19'] = () => repeat(3, () => scenarioPick('Round right: which reporting is appropriate?', [
  { text: 'A survey of 212 people, proportion in favour computed as 0.4716981.', answer: 'Report 47% (two significant figures match the precision)', why: 'With n = 212, the margin of error is about ±7 points; more digits are noise.' },
  { text: 'A mean reaction time measured to the millisecond, n = 2,000.', answer: 'Report to the nearest millisecond, e.g. 312 ms', why: 'Precision matches the measurement and the large sample.' },
  { text: 'A p-value computed as 0.0000003.', answer: 'Report p < .001', why: 'Below .001, exact tiny values add nothing and imply false precision.' },
  { text: 'An odds ratio of 1.4927 with 95% CI 0.9 to 2.4.', answer: 'Report OR = 1.49 (95% CI 0.90–2.44)', why: 'Two decimals suit the CI’s width; keep the interval.' },
], 4));
bespoke['W11.20'] = () => repeat(2, () => quizRound({ prompt: 'Rebuild the figure: a paper’s main figure cannot be regenerated because the authors did not share code and the data were “cleaned by hand in a spreadsheet”. Which practice would have prevented this?', choices: ['A scripted pipeline from raw data to figure, shared with the data and a random seed', 'A higher-resolution figure', 'More co-authors', 'A longer methods section'], answer: 0, why: 'Reproducibility means another person can run your code on your data and get your figure. Scripts, version control, shared data and fixed seeds make that possible.' }));
